    public function sign_in($params = array()): PromiseInterface {
        return Async\async(self::do_sign_in(...))($params);
    }

    private function do_sign_in($params = array()) {
        /**
         * obtains a live session token via the oauth 1.0a diffie-hellman exchange and opens the brokerage session, must be called prior to using other authenticated methods (called automatically by authenticate)
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/authentication/oauth-1-0-a/req-live-session-token
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} $response from the exchange
         */
        if ($this->safe_bool($this->options, 'useGateway', false)) {
            return Async\await($this->ibkr_gateway_sign_in($params));
        }
        $encryptionPemPath = $this->safe_string($this->options, 'encryptionPemPath');
        $dhParamPemPath = $this->safe_string($this->options, 'dhParamPemPath');
        if (!$encryptionPemPath || !$dhParamPemPath) {
            throw new ArgumentsRequired($this->id . ' supports two different authentication methods. You can either use the gateway or oauth 1.0 (if your account allows it) by providing encryptionPemPath and dhParamPemPath in options. Please check the FAQ for more details');
        }
        $this->ibkr_check_oauth_credentials();
        Async\await($this->init_file_system());
        $encryptionKey = $this->read_file($encryptionPemPath);
        $dhPrime = $this->convert_to_big_int('0x' . $this->read_dh_param($dhParamPemPath));
        // the access token secret is encrypted with the consumer's public encryption key
        $decrypted = $this->decrypt_private_key($encryptionKey, $this->secret);
        $accessTokenSecretHex = bin2hex($decrypted);
        $this->options['accessTokenSecretHex'] = $accessTokenSecretHex; // prepended to the signature base string in sign ()
        $this->options['serviceAccountsLoaded'] = false; // a new brokerage session needs iserver/accounts again
        $dhRandom = $this->convert_to_big_int('0x' . $this->random_bytes(32));
        $dhChallenge = $this->mod_pow($this->options['dhGen'], $dhRandom, $dhPrime);
        $request = array(
            'diffie_hellman_challenge' => $this->int_to_base16($dhChallenge),
        );
        $response = Async\await($this->webapiPostV1ApiOauthLiveSessionToken($this->extend($request, $params)));
        //
        //     {
        //         "diffie_hellman_response": "1d9c...",
        //         "live_session_token_signature": "9a7e...",
        //         "live_session_token_expiration": 1714661586311
        //     }
        //
        $dhResponse = $this->safe_string($response, 'diffie_hellman_response');
        $sharedSecret = $this->mod_pow($this->convert_to_big_int('0x' . $dhResponse), $dhRandom, $dhPrime);
        $liveSessionToken = $this->hmac($this->base16_to_binary($accessTokenSecretHex), $this->big_to_bytes($sharedSecret), 'sha1', 'base64');
        $check = $this->hmac($this->encode($this->options['consumer_key']), base64_decode($liveSessionToken), 'sha1', 'hex');
        if ($check !== $this->safe_string($response, 'live_session_token_signature')) {
            throw new AuthenticationError($this->id . ' signIn() live session token validation failed');
        }
        $this->options['liveSessionToken'] = $liveSessionToken;
        $this->options['liveSessionTokenExpiration'] = $this->safe_integer($response, 'live_session_token_expiration');
        // open the brokerage session
        $initRequest = $this->safe_dict($this->options, 'signInInitRequest', array());
        Async\await($this->webapiPostV1ApiIserverAuthSsodhInit($initRequest));
        Async\await($this->fetch_service_accounts());
        return $response;
    }

    public function authenticate($params = array()): PromiseInterface {
        return Async\async(self::do_authenticate(...))($params);
    }

    private function do_authenticate($params = array()) {
        /**
         * signs in when there is no live session token yet or the current one is about to expire
         * @ignore
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {string} the live session token
         */
        if ($this->ibkr_is_authenticated()) {
            return $this->safe_string($this->options, 'liveSessionToken');
        }
        // single-flight, see https://github.com/ccxt/ccxt/issues/29393
        // concurrent private calls on a cold (or expiring) instance would each pass the staleness
        // gate above and each run their own signIn (), so the first caller signs in and the rest
        // wait for it to finish, then reuse its token (or sign in themselves if the leader failed)
        if ($this->safe_bool($this->options, 'signInInProgress', false)) {
            $pollInterval = $this->safe_integer($this->options, 'signInPollInterval', 100);
            $maxWait = $this->safe_integer($this->options, 'signInMaxWait', 60000);
            $waited = 0;
            while ($this->safe_bool($this->options, 'signInInProgress', false) && ($waited < $maxWait)) {
                Async\await($this->sleep($pollInterval));
                $waited = $this->sum($waited, $pollInterval);
            }
            if ($this->ibkr_is_authenticated()) {
                return $this->safe_string($this->options, 'liveSessionToken');
            }
        }
        $this->options['signInInProgress'] = true;
        try {
            Async\await($this->sign_in($params));
        } catch (Exception $e) {
            $this->options['signInInProgress'] = false;
            throw $e;
        }
        $this->options['signInInProgress'] = false;
        return $this->safe_string($this->options, 'liveSessionToken');
    }

    public function ibkr_is_authenticated(): bool {
        /**
         * true when the current session can be used without signing in again, with options.useGateway the gateway session was confirmed authenticated within options.gatewayAuthCheckInterval ms, otherwise the oauth live session token is fresh
         * @ignore
         * @return {boolean} whether the current session can be used
         */
        if (!$this->safe_bool($this->options, 'useGateway', false)) {
            return $this->ibkr_has_fresh_session_token();
        }
        $authenticatedTimestamp = $this->safe_integer($this->options, 'gatewayAuthenticatedTimestamp');
        if ($authenticatedTimestamp === null) {
            return false;
        }
        $checkInterval = $this->safe_integer($this->options, 'gatewayAuthCheckInterval', 120000);
        return $this->milliseconds() < $this->sum($authenticatedTimestamp, $checkInterval);
    }

    public function ibkr_gateway_sign_in($params = array()): PromiseInterface {
        return Async\async(self::do_ibkr_gateway_sign_in(...))($params);
    }

    private function do_ibkr_gateway_sign_in($params = array()) {
        /**
         * checks that the client portal gateway session is $authenticated (taking the brokerage session back via ssodh/init options.autoRegainSession seconds after it was lost), loads the trading accounts and starts the keep-alive loop
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-brokerage-status
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the iserver/auth/status $response
         */
        $response = Async\await($this->webapiPostV1ApiIserverAuthStatus($params));
        //
        //     {
        //         "authenticated": true,
        //         "established": true,
        //         "competing": false,
        //         "connected": true,
        //         "message": "",
        //         "MAC": "06:A5:C8:3D:7F:EC",
        //         "serverInfo": { "serverName": "JifZ18024", "serverVersion": "Build 10.50.1e, Oct 26, 2026 5:04:19 PM" },
        //         "hardware_info": "6b0d051e|06:A5:C8:3D:7F:EC",
        //         "fail": ""
        //     }
        //
        $authenticated = $this->safe_bool($response, 'authenticated', false);
        $established = $this->safe_bool($this->options, 'gatewaySessionEstablished', false);
        $openOnStart = $this->safe_bool($this->options, 'gatewayReauthenticate', true);
        if (!$authenticated && !$established && $openOnStart) {
            // the first sign in of this instance opens the brokerage session right away
            $response = Async\await($this->ibkr_gateway_regain_session($params));
            $authenticated = $this->safe_bool($response, 'authenticated', false);
            if (!$authenticated) {
                $gatewayUrl = $this->safe_string($this->options, 'gatewayUrl');
                throw new AuthenticationError($this->id . ' the client portal gateway session is not authenticated, log in at ' . $gatewayUrl . ' in a browser, ' . $this->json($response));
            }
        }
        if (!$authenticated) {
            // the sso login is alive but the brokerage session is not (e.g. taken over by a login with the same username elsewhere, or after the daily reset)
            $lostTimestamp = $this->ibkr_gateway_on_session_lost();
            $regainDelay = $this->ibkr_gateway_regain_delay();
            if ($regainDelay <= 0) {
                $gatewayUrl = $this->safe_string($this->options, 'gatewayUrl');
                throw new AuthenticationError($this->id . ' the brokerage session of the client portal gateway is not authenticated (e.g. it was taken over by a login with the same username elsewhere), log in again at ' . $gatewayUrl . ' in a browser or set options.autoRegainSession to take it back automatically, ' . $this->json($response));
            }
            $regainTimestamp = $this->sum($lostTimestamp, $regainDelay);
            if ($this->milliseconds() < $regainTimestamp) {
                throw new AuthenticationError($this->id . ' the brokerage session of the client portal gateway is not authenticated (e.g. it was taken over by a login with the same username elsewhere), it will be taken back at ' . $this->iso8601($regainTimestamp) . ' (options.autoRegainSession), ' . $this->json($response));
            }
            $response = Async\await($this->ibkr_gateway_regain_session($params));
            $authenticated = $this->safe_bool($response, 'authenticated', false);
            if (!$authenticated) {
                // try again options.autoRegainSession seconds later
                $this->options['gatewaySessionLostTimestamp'] = $this->milliseconds();
                $this->ibkr_gateway_schedule_regain();
                throw new AuthenticationError($this->id . ' failed to take back the brokerage session of the client portal gateway, retrying at ' . $this->iso8601($this->sum($this->milliseconds(), $regainDelay)) . ' (options.autoRegainSession), ' . $this->json($response));
            }
        }
        $this->options['gatewaySessionLostTimestamp'] = null;
        $this->options['serviceAccountsLoaded'] = false;
        Async\await($this->fetch_service_accounts());
        $this->options['gatewaySessionEstablished'] = true;
        $this->options['gatewayAuthenticatedTimestamp'] = $this->milliseconds();
        $this->ibkr_gateway_start_keep_alive();
        return $response;
    }

    public function ibkr_gateway_regain_session($params = array()): PromiseInterface {
        return Async\async(self::do_ibkr_gateway_regain_session(...))($params);
    }

    private function do_ibkr_gateway_regain_session($params = array()) {
        /**
         * opens the brokerage session of the client portal gateway with POST iserver/auth/ssodh/init (taking it over from any other login with the same username) and polls iserver/auth/status until it is authenticated
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the last iserver/auth/status $response
         */
        $initRequest = $this->safe_dict($this->options, 'signInInitRequest', array());
        Async\await($this->webapiPostV1ApiIserverAuthSsodhInit($initRequest));
        $retries = $this->safe_integer($this->options, 'gatewayReauthenticateRetries', 5);
        $retryDelay = $this->safe_integer($this->options, 'gatewayReauthenticateDelay', 1000);
        $response = array();
        for ($i = 0; $i < $retries; $i++) {
            Async\await($this->sleep($retryDelay));
            $response = Async\await($this->webapiPostV1ApiIserverAuthStatus($params));
            if ($this->safe_bool($response, 'authenticated', false)) {
                break;
            }
        }
        return $response;
    }

    public function ibkr_gateway_regain_delay(): int {
        /**
         * options.autoRegainSession in milliseconds, 0 when the lost brokerage session must not be taken back
         * @ignore
         * @return {int} the delay in milliseconds
         */
        $seconds = $this->safe_number($this->options, 'autoRegainSession', 0);
        if (($seconds === null) || ($seconds <= 0)) {
            return 0;
        }
        return $this->parse_to_int($seconds * 1000);
    }

    public function ibkr_gateway_on_session_lost(): int {
        /**
         * marks the brokerage session as lost and schedules taking it back, see options.autoRegainSession
         * @ignore
         * @return {int} the timestamp when the session was found lost
         */
        $this->options['gatewayAuthenticatedTimestamp'] = null;
        $lostTimestamp = $this->safe_integer($this->options, 'gatewaySessionLostTimestamp');
        if ($lostTimestamp === null) {
            $lostTimestamp = $this->milliseconds();
            $this->options['gatewaySessionLostTimestamp'] = $lostTimestamp;
            $this->ibkr_gateway_schedule_regain();
        }
        return $lostTimestamp;
    }

    public function ibkr_gateway_schedule_regain(): bool {
        /**
         * schedules taking the lost brokerage session back options.autoRegainSession seconds after it was lost, so it is regained even when no private calls are made, the synchronous python and php versions take it back on the next private call instead
         * @ignore
         * @return {boolean} true if it was scheduled
         */
        $regainDelay = $this->ibkr_gateway_regain_delay();
        if (($regainDelay <= 0) || $this->safe_bool($this->options, 'gatewayRegainScheduled', false)) {
            return false;
        }
        $lostTimestamp = $this->safe_integer($this->options, 'gatewaySessionLostTimestamp', $this->milliseconds());
        $wait = $this->sum($lostTimestamp, $regainDelay) - $this->milliseconds();
        if ($wait <= 0) {
            $wait = $regainDelay;
        }
        try {
            $this->delay($wait, array($this, 'ibkr_gateway_regain_loop'));
            $this->options['gatewayRegainScheduled'] = true;
        } catch (Exception $e) {
            $this->options['gatewayRegainScheduled'] = false;
            return false;
        }
        return true;
    }

    public function ibkr_gateway_regain_loop(): PromiseInterface {
        return Async\async(self::do_ibkr_gateway_regain_loop(...))();
    }

    private function do_ibkr_gateway_regain_loop() {
        /**
         * takes the lost brokerage session back, rescheduled every options.autoRegainSession seconds until it succeeds, stops when it is set to 0 or the instance is closed
         * @ignore
         * @return {null}
         */
        $this->options['gatewayRegainScheduled'] = false;
        $useGateway = $this->safe_bool($this->options, 'useGateway', false);
        $lostTimestamp = $this->safe_integer($this->options, 'gatewaySessionLostTimestamp');
        if (!$useGateway || ($lostTimestamp === null) || ($this->ibkr_gateway_regain_delay() <= 0)) {
            return null; // already regained, or disabled
        }
        try {
            Async\await($this->authenticate());
        } catch (Exception $e) {
            if ($e instanceof ExchangeClosedByUser) {
                return null;
            }
            if ($this->verbose) {
                $this->log('ibkrGatewayRegainLoop failed ' . $this->exception_message($e));
            }
            // e.g. the sso login is lost too (http 401), retry until it is logged in again at options.gatewayUrl
            if ($this->safe_integer($this->options, 'gatewaySessionLostTimestamp') !== null) {
                $this->ibkr_gateway_schedule_regain();
            }
        }
        return null;
    }

    public function ibkr_gateway_start_keep_alive(): bool {
        /**
         * schedules the keep-alive loop once, see options.gatewayKeepAlive
         * @ignore
         * @return {boolean} true if the loop is running
         */
        $keepAlive = $this->safe_bool($this->options, 'gatewayKeepAlive', true);
        if (!$keepAlive || $this->safe_bool($this->options, 'gatewayKeepAliveStarted', false)) {
            return $keepAlive;
        }
        $interval = $this->safe_integer($this->options, 'gatewayKeepAliveInterval', 60000);
        try {
            $this->delay($interval, array($this, 'ibkr_gateway_keep_alive'));
            $this->options['gatewayKeepAliveStarted'] = true;
        } catch (Exception $e) {
            // the synchronous python and php versions have no event loop to schedule on, the session is
            // then kept alive by the private calls, which re-check iserver/auth/status every gatewayAuthCheckInterval ms
            $this->options['gatewayKeepAliveStarted'] = false;
            return false;
        }
        return true;
    }

    public function ibkr_gateway_keep_alive(): PromiseInterface {
        return Async\async(self::do_ibkr_gateway_keep_alive(...))();
    }

    private function do_ibkr_gateway_keep_alive() {
        /**
         * keeps the client portal gateway session alive with POST /tickle every options.gatewayKeepAliveInterval ms and tracks its authentication status, stops when options.gatewayKeepAlive is set to false or the instance is closed
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-session-token
         *
         * @return {null}
         */
        $useGateway = $this->safe_bool($this->options, 'useGateway', false);
        $keepAlive = $this->safe_bool($this->options, 'gatewayKeepAlive', true);
        if (!$useGateway || !$keepAlive) {
            $this->options['gatewayKeepAliveStarted'] = false;
            return null;
        }
        try {
            $response = Async\await($this->webapiPostV1ApiTickle());
            //
            //     {
            //         "session": "dcbd01d969bfd9434139f372edc338b2",
            //         "ssoExpires": 237821,
            //         "collission": false,
            //         "userId": 46130428,
            //         "hmds": { "error": "no bridge" },
            //         "iserver": { "authStatus": { "authenticated": true, "established": true, "competing": false, "connected": true, ... } }
            //     }
            //
            $iserver = $this->safe_dict($response, 'iserver', array());
            $authStatus = $this->safe_dict($iserver, 'authStatus', array());
            if ($this->safe_bool($authStatus, 'authenticated', false)) {
                if ($this->safe_integer($this->options, 'gatewaySessionLostTimestamp') === null) {
                    $this->options['gatewayAuthenticatedTimestamp'] = $this->milliseconds();
                }
                // otherwise it was regained outside of this instance (e.g. a new login at options.gatewayUrl), the next private call re-loads the accounts
            } else {
                // e.g. taken over by a login with the same username elsewhere, see options.autoRegainSession
                $this->ibkr_gateway_on_session_lost();
            }
        } catch (Exception $e) {
            if ($e instanceof ExchangeClosedByUser) {
                $this->options['gatewayKeepAliveStarted'] = false;
                return null;
            }
            // a failing tickle (e.g. the gateway container restarts) is retried on the next interval
            $this->options['gatewayAuthenticatedTimestamp'] = null;
            if ($this->verbose) {
                $this->log('ibkrGatewayKeepAlive tickle failed ' . $this->exception_message($e));
            }
        }
        $interval = $this->safe_integer($this->options, 'gatewayKeepAliveInterval', 60000);
        $this->delay($interval, array($this, 'ibkr_gateway_keep_alive'));
        return null;
    }

    public function ibkr_has_fresh_session_token(): bool {
        /**
         * true when a live session token is set and is not about to expire
         * @ignore
         * @return {boolean} whether the current live session token can be used
         */
        $liveSessionToken = $this->safe_string($this->options, 'liveSessionToken');
        if ($liveSessionToken === null) {
            return false;
        }
        $expiration = $this->safe_integer($this->options, 'liveSessionTokenExpiration');
        if ($expiration === null) {
            return true;
        }
        $refreshMargin = $this->safe_integer($this->options, 'liveSessionTokenRefreshMargin', 60000);
        return $this->sum($this->milliseconds(), $refreshMargin) < $expiration;
    }

    public function load_account_id($params = array()): PromiseInterface {
        return Async\async(self::do_load_account_id(...))($params);
    }

    private function do_load_account_id($params = array()) {
        /**
         * returns the account id from $params, options, or the first account returned by fetchAccounts
         * @ignore
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id to use
         * @return {Array} the account id and the $params without $accountId
         */
        list($accountIdFromParams, $query) = $this->handle_option_and_params($params, 'loadAccountId', 'accountId');
        $accountId = $accountIdFromParams;
        if ($accountId === null) {
            Async\await($this->fetch_accounts());
            $accountId = $this->safe_string($this->options, 'accountId');
        }
        if ($accountId === null) {
            throw new ArgumentsRequired($this->id . ' requires an accountId in params["accountId"] or options["accountId"], fetchAccounts() returned no accounts');
        }
        return array( $accountId, $query );
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * $query for balance and get the amount of funds available for trading or funds locked in orders, the cash comes from the ledger, the crypto holdings from the positions and the locked ('used') amounts from the open orders of the current brokerage session
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-portfolio-ledger
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-uncached-positions
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-open-orders
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to options["accountId"] or the selected account
         * @param {boolean} [$params->positions] add the holdings of options.fetchBalance.positionAssetClasses (crypto by default) as balances, default true
         * @param {boolean} [$params->openOrders] compute the locked ('used') amounts from the open orders, default true
         * @return {array} a ~@link https://docs.ccxt.com/?id=balance-structure balance structure~
         */
        Async\await($this->authenticate());
        list($accountId, $accountQuery) = Async\await($this->load_account_id($params));
        list($withPositions, $positionsQuery) = $this->handle_option_and_params($accountQuery, 'fetchBalance', 'positions', true);
        list($withOpenOrders, $query) = $this->handle_option_and_params($positionsQuery, 'fetchBalance', 'openOrders', true);
        $request = array(
            'accountId' => $accountId,
        );
        if ($withPositions || $withOpenOrders) {
            // the conids of the positions and orders are resolved to currencies via the markets
            if ($this->markets === null) {
                Async\await($this->load_markets());
            }
        }
        $promises = array();
        $promises[] = $this->webapiGetV1ApiPortfolioAccountIdLedger($this->extend($request, $query));
        if ($withPositions) {
            $promises[] = $this->webapiGetV1ApiPortfolio2AccountIdPositions($request);
            //
            //     [
            //         {
            //             "position": 0.04,
            //             "conid": "495759171",
            //             "avgCost": 2428.04,
            //             "currency": "USD",
            //             "description": "ETH CRYPTO",
            //             "secType": "CRYPTO",
            //             ...
            //         }
            //     ]
            //
        }
        if ($withOpenOrders) {
            $promises[] = $this->fetch_live_orders_raw();
        }
        $results = Async\await(Promise\all($promises));
        $response = $this->safe_dict($results, 0, array());
        //
        //     {
        //         "USD": {
        //             "commoditymarketvalue": 0.0,
        //             "futuremarketvalue": 0.0,
        //             "settledcash": 214716688.0,
        //             "exchangerate": 1,
        //             "sessionid": 1,
        //             "cashbalance": 214716688.0,
        //             "corporatebondsmarketvalue": 0.0,
        //             "netliquidationvalue": 215335840.0,
        //             "interest": 305569.94,
        //             "unrealizedpnl": 39695.82,
        //             "stockmarketvalue": 314123.88,
        //             "currency": "USD",
        //             "realizedpnl": 0.0,
        //             "acctcode": "U1234567",
        //             "key": "LedgerList",
        //             "timestamp": 1702582321,
        //             "secondkey": "USD",
        //             ...
        //         },
        //         "BASE": { ... }
        //     }
        //
        $balanceResponse = array(
            'ledger' => $response,
        );
        $index = 1;
        if ($withPositions) {
            $balanceResponse['positions'] = $this->safe_list($results, $index);
            $index = $index + 1;
        }
        if ($withOpenOrders) {
            // the 'orders' key is present only when the open orders were fetched, then the currencies without open orders get used = 0
            $balanceResponse['orders'] = $this->safe_list($results, $index);
        }
        return $this->parse_balance($balanceResponse);
    }

    public function parse_balance(mixed $response): array {
        //
        //     {
        //         "ledger": { "USD": { "cashbalance": 1000.0, ... }, "BASE": { "timestamp": 1702582321, ... } },
        //         "positions": [ { "position": 0.04, "conid": "495759171", "description": "ETH CRYPTO", "secType": "CRYPTO", ... } ],
        //         "orders": [ { "conid": 479624278, "side": "BUY", "status": "Submitted", "price": "80000", "remainingQuantity": 0.001, "cashCcy": "USD", ... } ]
        //     }
        //
        $ledger = $this->safe_dict($response, 'ledger', $response);
        $positions = $this->safe_list($response, 'positions', array());
        $orders = $this->safe_list($response, 'orders', array());
        $result = array(
            'info' => $response,
        );
        // cash, from the ledger
        $currencyIds = is_array($ledger) ? array_keys($ledger) : array();
        for ($i = 0; $i < count($currencyIds); $i++) {
            $currencyId = $currencyIds[$i];
            if ($currencyId === 'BASE') {
                continue; // aggregated entry in the account base currency
            }
            $balance = $this->safe_dict($ledger, $currencyId);
            if ($balance === null) {
                continue;
            }
            $code = $this->safe_currency_code($currencyId);
            $account = $this->account();
            $account['total'] = $this->safe_string($balance, 'cashbalance');
            $result[$code] = $account;
        }
        // holdings, from the positions
        $balanceOptions = $this->safe_dict($this->options, 'fetchBalance', array());
        $positionAssetClasses = $this->safe_list($balanceOptions, 'positionAssetClasses', array( 'CRYPTO' ));
        for ($i = 0; $i < count($positions); $i++) {
            $position = $positions[$i];
            // portfolio2 positions have "secType", the cached portfolio positions have "assetClass"
            $assetClass = $this->safe_string_2($position, 'secType', 'assetClass');
            if (!$this->in_array($assetClass, $positionAssetClasses)) {
                continue;
            }
            $code = $this->ibkr_balance_code($position);
            if (($code === null) || (is_array($result) && array_key_exists($code ?? '', $result))) {
                continue; // the ledger takes precedence
            }
            $account = $this->account();
            $account['total'] = $this->safe_string($position, 'position');
            $result[$code] = $account;
        }
        // locked amounts, from the open orders: buy orders lock remaining * price of the quote currency, sell orders lock the remaining base amount
        $used = array();
        for ($i = 0; $i < count($orders); $i++) {
            $order = $orders[$i];
            $status = $this->parse_order_status($this->safe_string_2($order, 'status', 'order_status'));
            if ($status !== 'open') {
                continue;
            }
            $marketId = $this->safe_string($order, 'conid');
            $market = $this->safe_market($marketId);
            if ($this->safe_bool($market, 'contract', false)) {
                continue; // contracts lock margin, not the currencies, see fetchPositions
            }
            $remaining = $this->safe_string_2($order, 'remainingQuantity', 'size');
            if (($remaining === null) || !Precise::string_gt($remaining, '0')) {
                continue;
            }
            $side = $this->safe_string_upper($order, 'side');
            $code = null;
            $amount = null;
            if (($side === 'BUY') || ($side === 'B')) {
                $price = $this->omit_zero($this->safe_string_2($order, 'price', 'limit_price'));
                if ($price === null) {
                    continue; // market orders have no price to estimate the locked cost
                }
                $cashCurrencyId = $this->safe_string($order, 'cashCcy');
                if ($cashCurrencyId !== null) {
                    $code = $this->safe_currency_code($cashCurrencyId);
                } else {
                    $code = $this->safe_string($market, 'quote');
                }
                $amount = Precise::string_mul($remaining, $price);
            } elseif (($side === 'SELL') || ($side === 'S')) {
                $code = $this->safe_string($market, 'base');
                $amount = $remaining;
            }
            if (($code === null) || !(is_array($result) && array_key_exists($code ?? '', $result))) {
                continue; // no known total to lock the amount from
            }
            $previous = $this->safe_string($used, $code, '0');
            $used[$code] = Precise::string_add($previous, $amount);
        }
        $usedCodes = is_array($used) ? array_keys($used) : array();
        for ($i = 0; $i < count($usedCodes); $i++) {
            $code = $usedCodes[$i];
            $result[$code]['used'] = $used[$code];
        }
        // every currency of the ledger and the positions gets a 'used' when the open orders were fetched, so that 'free' is computed
        if (is_array($response) && array_key_exists('orders' ?? '', $response)) {
            $codes = is_array($result) ? array_keys($result) : array();
            for ($i = 0; $i < count($codes); $i++) {
                $code = $codes[$i];
                if (($code !== 'info') && ($this->safe_string($result[$code], 'used') === null)) {
                    $result[$code]['used'] = '0';
                }
            }
        }
        $timestamp = $this->safe_timestamp($this->safe_dict($ledger, 'BASE', array()), 'timestamp');
        $result['timestamp'] = $timestamp;
        $result['datetime'] = $this->iso8601($timestamp);
        return $this->safe_balance($result);
    }

    public function ibkr_balance_code(array $position): ?string {
        /**
         * resolves the currency code of a $position held as a balance, BTC for the BTC crypto, AAPL for the AAPL shares
         * @ignore
         * @param {array} $position a raw $position from portfolio2/{accountId}/positions
         * @return {string|null} the currency code
         */
        $marketId = $this->safe_string($position, 'conid');
        $market = $this->safe_market($marketId);
        $base = $this->safe_string($market, 'base');
        if ($base !== null) {
            return $base;
        }
        $description = $this->safe_string_2($position, 'ticker', 'description');
        if ($description === null) {
            return null;
        }
        $assetClass = $this->safe_string_2($position, 'secType', 'assetClass');
        $parts = explode(' ', $description);
        if ($assetClass === 'CRYPTO') {
            // "ETH CRYPTO" -> ETH
            return $this->safe_currency_code($parts[0]);
        }
        return implode('.', $parts); // 'BRK B' -> 'BRK.B', as in parseMarket
    }

    public function before_close(): mixed {
        /**
         * stops the client portal gateway keep-alive and session-regain loops when close () is called, otherwise the scheduled tickles keep the event loop alive after close ()
         * @ignore
         * @return {null}
         */
        $this->options['gatewayKeepAlive'] = false;
        $this->options['autoRegainSession'] = 0;
        return null;
    }

    public function load_markets($reload = false, $params = array()) {
        return Async\async(self::do_load_markets(...))($reload, $params);
    }

    private function do_load_markets($reload = false, $params = array()) {
        Async\await($this->authenticate());
        return Async\await(parent::load_markets($reload, $params));
    }

    public function fetch_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_markets(...))($params);
    }

    private function do_fetch_markets($params = array()) {
        /**
         * retrieves data on the market $types of $options->fetchMarkets.types => stocks of $options->fetchMarkets.exchanges.STK, crypto of $options->fetchMarkets.cryptoSpotSymbols, fx pairs of $options->fetchMarkets.forexCurrencies, coinbase derivatives perp-style futures discovered with the market scanner (as swap, e.g. BTC/USD:USD), dated coinbase derivatives futures (scanned) and CME and CFE crypto futures of $options->fetchMarkets.cryptoCmeFutureSymbols (as future, e.g. BTC/USD:USD-261127) and cfds of $options->fetchMarkets.cfdExchanges (as swap, e.g. AAPL/USD:USD), bonds of $options->fetchMarkets.bondSymbols are loaded only with 'bond' in $options->fetchMarkets.types (as spot, e.g. US-T-4.125-270131.SMART/USD), the market id is the IBKR conid
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-conids-by-exchange
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-bond-filters
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-info-and-rules
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-future-by-symbol
         * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-contract-symbols-from-body
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-currency-pairs
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-instrument-definition
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market data
         */
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $types = $this->safe_list($options, 'types', array());
        $promises = array();
        // the order matters, on symbol collisions the earlier contract keeps the plain symbol
        if ($this->in_array('stock', $types)) {
            $promises[] = $this->fetch_stock_markets($params);
        }
        if ($this->in_array('crypto', $types)) {
            $promises[] = $this->fetch_crypto_markets($params);
        }
        if ($this->in_array('forex', $types)) {
            $promises[] = $this->fetch_forex_markets($params);
        }
        if ($this->in_array('swap', $types) || $this->in_array('future', $types)) {
            // the swaps and the futures come from the same scans and requests
            $promises[] = $this->fetch_futures_and_swap_markets($params);
        }
        if ($this->in_array('cfd', $types)) {
            $promises[] = $this->fetch_cfd_markets($params);
        }
        if ($this->in_array('bond', $types)) {
            $promises[] = $this->fetch_bond_markets($params);
        }
        $results = Async\await(Promise\all($promises));
        $markets = $this->arrays_concat($results);
        // toArray is the identity on a list, it types the result as a list for the statically typed ports
        return $this->to_array($this->ibkr_disambiguate_contract_symbols($markets));
    }

    public function ibkr_disambiguate_contract_symbols(array $markets): array {
        /**
         * gives a unique $symbol to the contract $markets that share a $symbol with an earlier $market, e.g. the GRAYSCALE BITCOIN MINI ETF CFD (ticker BTC) and the BTC perp-style future both map to BTC/USD:USD, the cfd becomes BTC.IBUSCFD/USD:USD
         * @ignore
         * @param {array[]} $markets parsed $markets
         * @return {array[]} the $markets with unique symbols
         */
        $seen = array();
        $result = array();
        for ($i = 0; $i < count($markets); $i++) {
            $market = $this->extend(array(), $markets[$i]);
            $symbol = $this->safe_string($market, 'symbol');
            $isContract = $this->safe_bool($market, 'contract', false);
            if ((is_array($seen) && array_key_exists($symbol ?? '', $seen)) && $isContract) {
                $info = $this->safe_dict($market, 'info', array());
                $listingExchange = $this->safe_string_2($info, 'listingExchange', 'exchange', 'default');
                $marketBase = $this->safe_string($market, 'base');
                $marketBaseId = $this->safe_string($market, 'baseId');
                $isFuture = $this->safe_bool($market, 'future', false);
                // keeps the quote, settle and the expiry suffix of futures, e.g. /USD:USD-261127
                $symbolParts = explode('/', $symbol);
                $quoteAndSettle = '/' . $symbolParts[1];
                $base = $marketBase . '.' . $listingExchange;
                if ($isFuture && ($marketBaseId !== $marketBase)) {
                    // the futures of the same base and expiry (BRR, MBT, BFF) are told apart by the IBKR ticker, e.g. BTC.MBT/USD:USD-261127
                    $base = $marketBase . '.' . $marketBaseId;
                }
                $newSymbol = $base . $quoteAndSettle;
                if (is_array($seen) && array_key_exists($newSymbol ?? '', $seen)) {
                    $base = $marketBase . '.' . $this->safe_string($market, 'id');
                    $newSymbol = $base . $quoteAndSettle;
                }
                $market = $this->extend($market, array(
                    'symbol' => $newSymbol,
                    'base' => $base,
                ));
            }
            $finalSymbol = $this->safe_string($market, 'symbol');
            $seen[$finalSymbol] = true;
            $result[] = $market;
        }
        return $result;
    }

    public function fetch_sec_with_details(array $plainEntries) {
        return Async\async(self::do_fetch_sec_with_details(...))($plainEntries);
    }

    private function do_fetch_sec_with_details(array $plainEntries) {
        $detailIds = is_array($plainEntries) ? array_keys($plainEntries) : array();
        $entries = array();
        $numDetails = count($detailIds);
        if ($numDetails === 0) {
            return $entries;
        }
        $chunkSize = 330; // above this number, response becomes unreliable
        $promises = array();
        $offset = 0;
        while ($offset < $numDetails) {
            $end = min($this->sum($offset, $chunkSize), $numDetails);
            $chunk = $this->array_slice($detailIds, $offset, $end);
            $secdefRequest = array(
                'conids' => implode(',', $chunk),
            );
            $promises[] = $this->markets_endpoint_call($secdefRequest, 'webapiGetV1ApiTrsrvSecdef', array());
            $offset = $end;
        }
        $responses = Async\await(Promise\all($promises));
        //
        //     {
        //         "secdef": [
        //             {
        //                 "conid": 479624278,
        //                 "currency": "USD",
        //                 "incrementRules": [ { "lowerEdge": 0, "increment": 0.25 } ],
        //                 "listingExchange": "PAXOS",
        //                 "assetClass": "CRYPTO",
        //                 "ticker": "BTC",
        //                 ...
        //             }
        //         ]
        //     }
        //
        for ($i = 0; $i < count($responses); $i++) {
            $secdefs = $this->safe_list($responses[$i], 'secdef', array());
            for ($j = 0; $j < count($secdefs); $j++) {
                $secdef = $secdefs[$j];
                $conid = $this->safe_string($secdef, 'conid');
                $entry = $this->safe_dict($plainEntries, $conid);
                $entries[] = $this->extend($entry, $secdef);
            }
        }
        return $entries;
    }

    public function fetch_forex_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_forex_markets(...))($params);
    }

    private function do_fetch_forex_markets($params = array()) {
        $entries = array();
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $forexCurrencies = $this->safe_list($options, 'forexCurrencies', array());
        $promises = array();
        for ($i = 0; $i < count($forexCurrencies); $i++) {
            $fxCurrency = $forexCurrencies[$i];
            $pairsRequest = array(
                'currency' => $fxCurrency,
            );
            $promises[] = $this->markets_endpoint_call($this->extend($pairsRequest, $params), 'webapiGetV1ApiIserverCurrencyPairs', array());
            //
            //    { "USD": [ { "symbol": "EUR.USD", "conid": 12087792, "ccyPair": "EUR" } ] }
            //
        }
        $fxResults = Async\await(Promise\all($promises));
        for ($i = 0; $i < count($fxResults); $i++) {
            $pairsResponse = $fxResults[$i];
            $fxCurrency = $forexCurrencies[$i];
            $pairs = $this->safe_list($pairsResponse, $fxCurrency, array());
            for ($j = 0; $j < count($pairs); $j++) {
                $pair = $pairs[$j];
                $conid = $this->safe_string($pair, 'conid');
                if ($conid !== null) {
                    $entries[$conid] = $pair;
                }
            }
        }
        $detailMarkets = Async\await($this->fetch_sec_with_details($entries));
        return $this->parse_markets($detailMarkets);
    }

    public function fetch_crypto_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_crypto_markets(...))($params);
    }

    private function do_fetch_crypto_markets($params = array()) {
        $entries = array();
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $cryptoSpotSymbols = $this->safe_list($options, 'cryptoSpotSymbols', array());
        $promises = array();
        for ($i = 0; $i < count($cryptoSpotSymbols); $i++) {
            $cryptoSymbol = $cryptoSpotSymbols[$i];
            $searchRequest = array(
                'symbol' => $cryptoSymbol,
                'secType' => 'CRYPTO',
            );
            $promises[] = $this->markets_endpoint_call($this->extend($searchRequest, $params), 'webapiPostV1ApiIserverSecdefSearch', array());
            //
            //     [
            //         {
            //             "conid": "479624278",
            //             "companyName": "Bitcoin cryptocurrency",
            //             "symbol": "BTC",
            //             "sections": [ { "secType": "CRYPTO", "exchange": "PAXOS;" } ]
            //         },
            //         ...
            //     ]
            //
        }
        $results = Async\await(Promise\all($promises));
        $neededSecTypes = array( 'CRYPTO' ); // CFD, OPT - they should already be fetched in other calls
        for ($i = 0; $i < count($results); $i++) {
            $result = $results[$i];
            for ($j = 0; $j < count($result); $j++) {
                $entry = $result[$j];
                $sections = $this->safe_list($entry, 'sections', array());
                for ($k = 0; $k < count($sections); $k++) {
                    $secType = $this->safe_string($sections[$k], 'secType');
                    if ($this->in_array($secType, $neededSecTypes)) {
                        $conid = $this->safe_string($entry, 'conid');
                        if ($conid !== null) {
                            $entries[$conid] = $entry;
                        }
                    }
                }
            }
        }
        $detailMarkets = Async\await($this->fetch_sec_with_details($entries));
        return $this->parse_markets($detailMarkets);
    }

    public function fetch_coinbase_derivatives_symbols(): PromiseInterface {
        return Async\async(self::do_fetch_coinbase_derivatives_symbols(...))();
    }

    private function do_fetch_coinbase_derivatives_symbols() {
        /**
         * discovers the coinbase derivatives (COINDERIV) futures symbols with the market scanner, the MOST_ACTIVE scan misses the $contracts that have not traded yet, so it is merged with the NOT_YET_TRADED_TODAY scan
         * @ignore
         *
         * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
         *
         * @return {string[]} the unique IBKR symbols, e.g. array( 'BIP', 'ETP', 'BIT', ... )
         */
        $scanTypes = array( 'MOST_ACTIVE', 'NOT_YET_TRADED_TODAY' ); // these two ones cover all coinbase symbols
        $result = array();
        // the scans are run one by one, the scanner rejects concurrent requests
        for ($i = 0; $i < count($scanTypes); $i++) {
            if ($i !== 0) {
                Async\await($this->sleep(1000)); // wait for 1 second before running the next scan
            }
            $request = array(
                'instrument' => 'FUT.US',
                'location' => 'FUT.COINDERIV',
                'type' => $scanTypes[$i],
                'filter' => array(),
            );
            $response = Async\await($this->markets_endpoint_call($request, 'webapiPostV1ApiIserverScannerRun', array()));
            //
            //     {
            //         "contracts": [
            //             {
            //                 "server_id": "0",
            //                 "column_name": "Volume",
            //                 "symbol": "BIP",
            //                 "conidex": "805366677@COINDERIV",
            //                 "con_id": 805366677,
            //                 "company_name": "nano Bitcoin BTC Perpetual Futures",
            //                 "contract_description_1": "Dec'30",
            //                 "listing_exchange": "COINDERIV",
            //                 "sec_type": "FUT"
            //             }
            //         ],
            //         "scan_data_column_name": "Volume"
            //     }
            //
            $contracts = $this->safe_list($response, 'contracts', array());
            for ($j = 0; $j < count($contracts); $j++) {
                $contract = $contracts[$j];
                $listingExchange = $this->safe_string($contract, 'listing_exchange');
                $symbol = $this->safe_string($contract, 'symbol');
                if (($symbol !== null) && ($listingExchange === 'COINDERIV') && !$this->in_array($symbol, $result)) {
                    $result[] = $symbol;
                }
            }
        }
        return $result;
    }

    public function fetch_futures_and_swap_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_futures_and_swap_markets(...))($params);
    }

    private function do_fetch_futures_and_swap_markets($params = array()) {
        /**
         * retrieves the coinbase derivatives (COINDERIV) perp-style futures (as swaps) and dated futures, whose $symbols are discovered with the $market scanner, together with the CME and CFE dated crypto futures of $options->fetchMarkets.cryptoCmeFutureSymbols, the swaps are kept with 'swap' in $options->fetchMarkets.types and the futures with 'future'
         * @ignore
         *
         * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-future-by-symbol
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing $market data
         */
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $types = $this->safe_list($options, 'types', array());
        $cryptoCmeFutureSymbols = $this->safe_dict($options, 'cryptoCmeFutureSymbols', array());
        $cryptoCboeFutureSymbols = $this->safe_dict($options, 'cryptoCboeFutureSymbols', array());
        $coinbaseDerivSymbols = Async\await($this->fetch_coinbase_derivatives_symbols());
        $cmeSymbols = is_array($cryptoCmeFutureSymbols) ? array_keys($cryptoCmeFutureSymbols) : array();
        $cfeSymbols = is_array($cryptoCboeFutureSymbols) ? array_keys($cryptoCboeFutureSymbols) : array();
        $targetSymbols = $this->arrays_concat(array( $coinbaseDerivSymbols, $cmeSymbols, $cfeSymbols ));
        $symbols = $this->unique($targetSymbols);
        $request = array(
            'symbols' => implode(',', $symbols),
        );
        $response = Async\await($this->markets_endpoint_call($this->extend($request, $params), 'webapiGetV1ApiTrsrvFutures', array()));
        //
        //     {
        //         "MBT": [
        //             {
        //                 "symbol": "MBT",
        //                 "conid": 750093370,
        //                 "underlyingConid": 479624278,
        //                 "expirationDate": 20261127,
        //                 "ltd": 20261127,
        //                 "shortFuturesCutOff": 20261127,
        //                 "longFuturesCutOff": 20261127
        //             }
        //         ]
        //     }
        //
        // (for swaps, the date is "20301220")
        //
        $entries = array();
        for ($i = 0; $i < count($symbols); $i++) {
            $contracts = $this->safe_list($response, $symbols[$i], array());
            for ($j = 0; $j < count($contracts); $j++) {
                $contract = $contracts[$j];
                $conid = $this->safe_string($contract, 'conid');
                if ($conid !== null) {
                    $entries[$conid] = $contract;
                }
            }
        }
        $details = Async\await($this->fetch_sec_with_details($entries));
        // generic tickers (e.g. SOL, XRP, ADA, XLM) are queried by bare symbol, so trsrv/futures can return
        // unrelated contracts listed on other venues (e.g. EUREX), only the crypto futures venues are kept
        $allowedVenues = array( 'CME', 'CFE', 'COINDERIV' );
        $detailMarkets = array();
        for ($i = 0; $i < count($details); $i++) {
            $detail = $details[$i];
            $venue = $this->safe_string($detail, 'listingExchange');
            if ($this->in_array($venue, $allowedVenues)) {
                $detailMarkets[] = $detail;
            }
        }
        $markets = $this->parse_markets($detailMarkets);
        $withSwaps = $this->in_array('swap', $types);
        $withFutures = $this->in_array('future', $types);
        $result = array();
        for ($i = 0; $i < count($markets); $i++) {
            $market = $markets[$i];
            $parsedType = $this->safe_string($market, 'type');
            if ($withSwaps && ($parsedType === 'swap')) {
                $result[] = $market;
            } elseif ($withFutures && ($parsedType === 'future')) {
                $result[] = $market;
            }
        }
        return $result;
    }

    public function fetch_cfd_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_cfd_markets(...))($params);
    }

    private function do_fetch_cfd_markets($params = array()) {
        /**
         * retrieves the $cfd contracts listed on $options->fetchMarkets.cfdExchanges
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-conids-by-exchange
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market data
         */
        $entries = array();
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $cfdExchanges = $this->safe_list($options, 'cfdExchanges', array());
        $promises = array();
        for ($i = 0; $i < count($cfdExchanges); $i++) {
            $request = array(
                'exchange' => $cfdExchanges[$i],
                'assetClass' => 'CFD',
            );
            $promises[] = $this->markets_endpoint_call($request, 'webapiGetV1ApiTrsrvAllConids', array());
            //
            //     [ { "ticker": "AAPL", "conid": 120549942, "exchange": null } ]
            //
        }
        $responses = Async\await(Promise\all($promises));
        for ($i = 0; $i < count($responses); $i++) {
            $cfds = $responses[$i];
            for ($j = 0; $j < count($cfds); $j++) {
                $cfd = $cfds[$j];
                $conid = $this->safe_string($cfd, 'conid');
                $entries[$conid] = $cfd;
            }
        }
        $detailMarkets = Async\await($this->fetch_sec_with_details($entries));
        // keep the order of options.fetchMarkets.cfdExchanges, the first exchange wins the plain symbol on collisions
        $result = array();
        for ($i = 0; $i < count($cfdExchanges); $i++) {
            for ($j = 0; $j < count($detailMarkets); $j++) {
                $detail = $detailMarkets[$j];
                if ($this->safe_string($detail, 'listingExchange') === $cfdExchanges[$i]) {
                    $result[] = $detail;
                }
            }
        }
        return $this->parse_markets($result);
    }

    public function fetch_bond_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_bond_markets(...))($params);
    }

    private function do_fetch_bond_markets($params = array()) {
        /**
         * retrieves the bonds of the $issuers of $options->fetchMarkets.bondSymbols, narrowed by $options->fetchMarkets.bondFilters
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-$contract-symbols-from-body
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-bond-filters
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-info-and-rules
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing $market data
         */
        $entries = array();
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $bondSymbols = $this->safe_list($options, 'bondSymbols', array());
        $bondFilters = $this->safe_dict($options, 'bondFilters', array());
        $searchPromises = array();
        for ($i = 0; $i < count($bondSymbols); $i++) {
            $searchRequest = array(
                'symbol' => $bondSymbols[$i],
                'secType' => 'BOND',
            );
            $searchPromises[] = $this->markets_endpoint_call($this->extend($searchRequest, $params), 'webapiPostV1ApiIserverSecdefSearch', array());
            //
            //     [
            //         {
            //             "issuers": [
            //                 { "id": "e1359061", "name": "United States Treasury" },
            //                 { "id": "e3773654", "name": "United States Treasury Floating Rate Note" }
            //             ],
            //             "bondid": 0,
            //             "conid": "2147483647",
            //             "companyHeader": "Government Fixed Income",
            //             "sections": [ { "secType": "BOND" } ]
            //         }
            //     ]
            //
        }
        $searchResults = Async\await(Promise\all($searchPromises));
        // the filters are sent as columnId:value pairs joined by a comma, e.g. 29:Notes,27:202701
        $filterIds = is_array($bondFilters) ? array_keys($bondFilters) : array();
        $filterParts = array();
        for ($i = 0; $i < count($filterIds); $i++) {
            $filterId = $filterIds[$i];
            $filterParts[] = $filterId . ':' . $this->safe_string($bondFilters, $filterId);
        }
        $filterPartsLength = count($filterParts);
        $contractPromises = array();
        for ($i = 0; $i < count($searchResults); $i++) {
            $searchResult = $searchResults[$i];
            for ($j = 0; $j < count($searchResult); $j++) {
                $issuers = $this->safe_list($searchResult[$j], 'issuers', array());
                for ($k = 0; $k < count($issuers); $k++) {
                    $contractsRequest = array(
                        'sectype' => 'BOND',
                        'issuerId' => $this->safe_string($issuers[$k], 'id'),
                    );
                    if ($filterPartsLength > 0) {
                        $contractsRequest['filters'] = implode(',', $filterParts);
                    }
                    $contractPromises[] = $this->markets_endpoint_call($contractsRequest, 'webapiGetV1ApiIserverSecdefInfo', array());
                }
            }
        }
        $contractResults = Async\await(Promise\all($contractPromises));
        //
        //     [
        //         {
        //             "conid": 758087005,
        //             "symbol": "US-T",
        //             "secType": "BOND",
        //             "exchange": "SMART",
        //             "listingExchange": "SMART",
        //             "right": "?",
        //             "strike": 0.0,
        //             "currency": "USD",
        //             "cusip": "IBCID758087005",
        //             "coupon": "4.125", // "No Coupon" for bills and strips
        //             "desc1": "US-T",
        //             "desc2": "GOVT Notes 4.125 Jan31'27 IBCID758087005",
        //             "maturityDate": "20270131",
        //             "multiplier": null,
        //             "tradingClass": "US-T",
        //             "validExchanges": "SMART"
        //         }
        //     ]
        //
        for ($i = 0; $i < count($contractResults); $i++) {
            $contracts = $contractResults[$i];
            for ($j = 0; $j < count($contracts); $j++) {
                $contract = $contracts[$j];
                $conid = $this->safe_string($contract, 'conid');
                if ($conid !== null) {
                    $entries[$conid] = $contract;
                }
            }
        }
        $detailMarkets = Async\await($this->fetch_sec_with_details($entries));
        $markets = $this->parse_markets($detailMarkets);
        // bonds sharing the issuer, coupon and maturity (e.g. a bill and a strip) are told apart by the conid, e.g. US-T-270215-265342934.SMART/USD
        $seen = array();
        $result = array();
        for ($i = 0; $i < count($markets); $i++) {
            $market = $this->extend(array(), $markets[$i]);
            $symbol = $this->safe_string($market, 'symbol');
            if (is_array($seen) && array_key_exists($symbol ?? '', $seen)) {
                $base = $this->safe_string($market, 'base') . '-' . $this->safe_string($market, 'id');
                $symbol = $base . '.' . $this->safe_string($market['info'], 'exchange', 'SMART') . '/' . $this->safe_string($market, 'quote');
                $market = $this->extend($market, array(
                    'symbol' => $symbol,
                    'base' => $base,
                ));
            }
            $seen[$symbol] = true;
            $result[] = $market;
        }
        return $result;
    }

    public function fetch_stock_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_stock_markets(...))($params);
    }

    private function do_fetch_stock_markets($params = array()) {
        $entries = array();
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $exchangesDict = $this->safe_dict($options, 'exchanges', array());
        $stockExchanges = $this->safe_list($exchangesDict, 'STK', array());
        for ($j = 0; $j < count($stockExchanges); $j++) {
            $exchange = $stockExchanges[$j];
            $stockRequest = array(
                'exchange' => $exchange,
                'assetClass' => 'STK',
            );
            $stocks = Async\await($this->markets_endpoint_call($this->extend($stockRequest, $params), 'webapiGetV1ApiTrsrvAllConids', array()));
            //
            //     [ { "ticker": "AAPL", "conid": 265598, "exchange": "NMS" } ]
            //
            for ($k = 0; $k < count($stocks); $k++) {
                $stock = $stocks[$k];
                $stockConid = $this->safe_string($stock, 'conid');
                if ($stockConid !== null) {
                    $entries[$stockConid] = $stock;
                }
            }
        }
        $markets = Async\await($this->fetch_sec_with_details($entries));
        return $this->parse_markets($markets);
    }

    public function markets_endpoint_call(array $request, string $ep, mixed $defaultValue = null) {
        return Async\async(self::do_markets_endpoint_call(...))($request, $ep, $defaultValue);
    }

    private function do_markets_endpoint_call(array $request, string $ep, mixed $defaultValue = null) {
        $opts = $this->safe_dict($this->options, 'fetchMarkets', array());
        $retries = $this->safe_integer($opts, 'endpointRetries', 3);
        $retryDelay = $this->safe_integer($opts, 'retryDelay', 1000);
        for ($i = 0; $i < $retries; $i++) {
            $isLastRetry = ($i >= $retries - 1);
            $data = null;
            try {
                if ($ep === 'webapiGetV1ApiTrsrvSecdef') {
                    $data = Async\await($this->webapiGetV1ApiTrsrvSecdef($request));
                } elseif ($ep === 'webapiPostV1ApiIserverScannerRun') {
                    $retryDelay = max($retryDelay, 1000);
                    $data = Async\await($this->webapiPostV1ApiIserverScannerRun($request));
                } elseif ($ep === 'webapiGetV1ApiTrsrvFutures') {
                    $data = Async\await($this->webapiGetV1ApiTrsrvFutures($request));
                } elseif ($ep === 'webapiPostV1ApiIserverSecdefSearch') {
                    $data = Async\await($this->webapiPostV1ApiIserverSecdefSearch($request));
                } elseif ($ep === 'webapiGetV1ApiTrsrvAllConids') {
                    $data = Async\await($this->webapiGetV1ApiTrsrvAllConids($request));
                } elseif ($ep === 'webapiGetV1ApiIserverCurrencyPairs') {
                    $data = Async\await($this->webapiGetV1ApiIserverCurrencyPairs($request));
                } elseif ($ep === 'webapiGetV1ApiIserverSecdefInfo') {
                    $data = Async\await($this->webapiGetV1ApiIserverSecdefInfo($request));
                }
            } catch (Exception $e) {
                if ($e instanceof NullResponse) {
                    $data = $defaultValue;
                }
                if ($data === null) {
                    if ($isLastRetry) {
                        throw $e;
                    }
                    Async\await($this->sleep($retryDelay));
                }
            }
            if ($data !== null) {
                return $data;
            }
        }
        return null;
    }

    public function parse_market(array $market): array {
        //
        //    {
        //        "conid": 479624278,
        //        "symbol": "BTC", // "BTC", "EUR.USD",
        //        "incrementRules": [
        //            {
        //                "lowerEdge": 0,
        //                "increment": 0.25
        //            }
        //        ],
        //        "displayRule": {
        //            "magnification": 0,
        //            "displayRuleStep": [
        //                {
        //                    "decimalDigits": 2,
        //                    "lowerEdge": 0,
        //                    "wholeDigits": 4
        //                }
        //            ]
        //        },
        //        "currency": "USD",
        //        "time": 11,
        //        "chineseName": "&#x7F8E;&#x5143;",
        //        "allExchanges": "PAXOS",        // OTC, PAXOS, ...
        //        "listingExchange": "PAXOS",
        //        "countryCode": "US",
        //        "name": "Bitcoin cryptocurrency",
        //        "assetClass": "CRYPTO",     // CRYPTO, CASH ..
        //        "expiry": null,
        //        "lastTradingDay": null,
        //        "group": null,
        //        "putOrCall": null,
        //        "sector": null,
        //        "sectorGroup": null,
        //        "strike": "0",
        //        "ticker": "BTC",            // BTC, EUR
        //        "undConid": 0,
        //        "multiplier": 0,
        //        "type": "",
        //        "hasOptions": false,
        //        "fullName": "BTC",          // BTC, EUR.USD
        //        "isEventContract": false,
        //        "companyHeader": "Bitcoin cryptocurrency",  // in CRYPTO
        //        "companyName": "Bitcoin cryptocurrency",    // in CRYPTO
        //        "description": null,                        // in CRYPTO
        //        "restricted": null,                         // in CRYPTO
        //        "sections": [                               // in CRYPTO
        //            {
        //                "secType": "CRYPTO",
        //                "exchange": "PAXOS;"
        //            }
        //        ],
        //        "isUS": true,                               // in Stock
        //        "exchange": "NYSE",                         // in Stock
        //        "ccyPair": "EUR",                           // in Forex
        //    }
        //
        // perp-style future (FUT): "ticker": "BIP", "assetClass": "FUT", "listingExchange": "COINDERIV", "multiplier": 0.01, "expiry": "20301220", "undConid": 805366629
        // dated future (FUT): "ticker": "MBT", "assetClass": "FUT", "listingExchange": "CME", "multiplier": 0.1, "expiry": "20261127", "expirationDate": 20261127
        // cfd (CFD): "ticker": "AAPL", "assetClass": "CFD", "listingExchange": "IBUSCFD", "multiplier": 0, "undConid": 265598, "fullName": "APPLE INC CFD"
        // bond (BOND): "ticker": "US-T", "assetClass": "BOND", "exchange": "SMART", "listingExchange": "BONDDESKG", "coupon": "4.125", "maturityDate": "20270131", "type": "Govt", "fullName": "US-T Govt Notes 4.125 Jan31'27", "bond": { "t2": "Notes", "principalValue": 1000.0, "couponType": "FIXED", ... }
        //
        $assetClass = $this->safe_string($market, 'assetClass');
        $isCrypto = ($assetClass === 'CRYPTO');
        $isForex = ($assetClass === 'CASH');
        $isStock = ($assetClass === 'STK');
        $isBond = ($assetClass === 'BOND');
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $baseTickerId = $this->safe_string_2($market, 'ticker', 'symbol');
        $listingExchange = $this->safe_string_2($market, 'listingExchange', 'exchange', 'default');
        if ($isBond) {
            // bonds trade across many venues (BONDDESKG, TRADEWEBG, ...) and are routed by SMART, the listing exchange is an arbitrary one of them
            $listingExchange = $this->safe_string($market, 'exchange', 'SMART');
        }
        $name = $this->safe_string($market, 'name', '');
        $nameLower = strtolower($name);
        // coinbase derivatives perp-style futures are listed as FUT with a far (2030) nominal expiry, they are rolled with a funding adjustment, so they are unified as swaps
        // cfds are undated, cash-settled linear contracts on a stock, etf or index, also unified as swaps
        // the other FUT contracts (CME and coinbase derivatives dated crypto futures) are unified as futures
        $isCfd = ($assetClass === 'CFD');
        $isFut = ($assetClass === 'FUT');
        $expirationDate = $this->safe_string_2($market, 'expirationDate', 'expiry'); // 20261127
        $isCoinbaseDerivatives = ($listingExchange === 'COINDERIV');
        $isCme = ($listingExchange === 'CME');
        $isCfe = ($listingExchange === 'CFE');
        // checking for 'Perpetual' or 'Perp Style' in the name is weaker
        $isCoinbasePerp = $isCoinbaseDerivatives && ($expirationDate === '20301220'); // five year PERP cycle end
        $isPerpetual = $isCoinbasePerp; // no other perp providers
        $isPerp = ($isFut && $isPerpetual) || $isCfd;
        $isFuture = $isFut && !$isPerpetual;
        $isContract = $isFuture || $isPerp;
        $isSpot = !$isContract;
        $id = $this->safe_string($market, 'conid');
        $quoteId = $this->safe_string($market, 'currency');
        $quote = $this->safe_currency_code($quoteId);
        $incrementRules = $this->safe_list($market, 'incrementRules', array());
        $firstRule = $this->safe_dict($incrementRules, 0, array());
        $incrementTickSize = $this->safe_string($firstRule, 'increment');
        $amountPrecision = null;
        if ($isCrypto) {
            $amountPrecision = $this->safe_string($options, 'cryptoAmountIncrement', '0.00000001');
        } elseif ($isForex) {
            $amountPrecision = $this->safe_string($options, 'forexAmountIncrement', '1');
        } elseif ($isBond) {
            $amountPrecision = $this->safe_string($options, 'bondAmountIncrement', '1');
        } elseif ($isContract) {
            $amountPrecision = $this->safe_string($options, 'contractAmountIncrement', '1');
        } else {
            $amountPrecision = $this->safe_string($options, 'stockAmountIncrement', '1');
        }
        $cryptoCoinbasePerpSymbols = $this->safe_dict($options, 'cryptoCoinbasePerpSymbols', array());
        $cryptoCmeFutureSymbols = $this->safe_dict($options, 'cryptoCmeFutureSymbols', array());
        $cryptoCboeFutureSymbols = $this->safe_dict($options, 'cryptoCboeFutureSymbols', array());
        $microNanoPrefix = '';
        $base = $this->safe_currency_code($baseTickerId);
        $contractSize = null;
        $expiry = null;
        if ($isFut) {
            if ($isCoinbaseDerivatives) {
                $base = $this->safe_string($cryptoCoinbasePerpSymbols, $baseTickerId, $baseTickerId);
            } elseif ($isCme) {
                $base = $this->safe_string($cryptoCmeFutureSymbols, $baseTickerId, $baseTickerId);
            } elseif ($isCfe) {
                $base = $this->safe_string($cryptoCboeFutureSymbols, $baseTickerId, $baseTickerId);
            }
        }
        if ($isPerp && !$isCfd) {
            if (str_starts_with($nameLower, 'nano ')) {
                $microNanoPrefix = 'NANO.';
            }
            $contractSize = $this->safe_string($market, 'multiplier'); // 0.01 BTC for BIP
        } elseif ($isFuture) {
            if (str_starts_with($nameLower, 'nano ')) {
                $microNanoPrefix = 'NANO.';
            } elseif (str_starts_with($nameLower, 'micro ')) {
                $microNanoPrefix = 'MICRO.';
            } elseif (mb_strpos($name, 'New York Variant') !== -1) {
                $microNanoPrefix = 'NEWYORK.';
            }
            $contractSize = $this->safe_string($market, 'multiplier'); // 0.1 BTC for MBT, 5 BTC for BRR
            if ($expirationDate !== null) {
                $expiryDatetime = mb_substr($expirationDate, 0, 4 - 0) . '-' . mb_substr($expirationDate, 4, 6 - 4) . '-' . mb_substr($expirationDate, 6, 8 - 6) . 'T00:00:00Z';
                $expiry = $this->parse8601($expiryDatetime);
            }
        } elseif ($isBond) {
            // every bond of an issuer has the same ticker, the coupon and the maturity tell them apart, US-T-4.125-270131 (US-T-270114 without a coupon)
            $base = $baseTickerId;
            $coupon = $this->safe_string($market, 'coupon', ''); // "No Coupon" for bills and strips
            if (($coupon !== '') && (mb_strpos($coupon, ' ') === -1)) {
                $base = $base . '-' . $coupon;
            }
            $maturityDate = $this->safe_string($market, 'maturityDate'); // 20270131
            if ($maturityDate !== null) {
                $base = $base . '-' . mb_substr($maturityDate, 2, 8 - 2);
            }
        } elseif ($isStock || $isCfd) {
            // stock and cfd tickers are not currencies, skip commonCurrencies remapping, 'BRK B' -> 'BRK.B'
            $tickerParts = explode(' ', $baseTickerId);
            $base = implode('.', $tickerParts);
            if ($isCfd) {
                $contractSize = '1'; // one cfd is one share or index point, the multiplier is reported as 0 or 1
            }
        } else {
            if (!$isSpot) {
                $contractSize = $this->safe_string($this->options, 'defaultContractSize', '1');
            }
        }
        $symbol = $base . '.' . $microNanoPrefix . $listingExchange . '/' . $quote; // specific to IBKR
        $settleId = null;
        $settle = null;
        if ($isContract) {
            $settleId = $quoteId;
            $settle = $quote;
            $symbol = $symbol . ':' . $settle;
            if ($isFuture) {
                $symbol = $symbol . '-' . $this->yymmdd($expiry);
            }
        }
        $marketType = 'spot';
        if ($isPerp) {
            $marketType = 'swap';
        } elseif ($isFuture) {
            $marketType = 'future';
        }
        return $this->safe_market_structure(array(
            'id' => $id,
            'symbol' => $symbol,
            'quote' => $quote,
            'quoteId' => $quoteId,
            'base' => $base,
            'baseId' => $baseTickerId,
            'settle' => $settle,
            'settleId' => $settleId,
            'type' => $marketType,
            'spot' => $isSpot,
            'margin' => false,
            'swap' => $isPerp,
            'future' => $isFuture,
            'option' => false,
            'active' => true,
            'contract' => $isContract,
            'linear' => $isContract ? true : null,
            'inverse' => $isContract ? false : null,
            'contractSize' => $this->parse_number($contractSize),
            'expiry' => $expiry,
            'expiryDatetime' => $this->iso8601($expiry),
            'strike' => null,
            'optionType' => null,
            'precision' => array(
                'amount' => $this->parse_number($amountPrecision),
                'price' => $this->parse_number($incrementTickSize),
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => null,
                    'max' => null,
                ),
                'amount' => array(
                    'min' => null,
                    'max' => null,
                ),
                'price' => array(
                    'min' => null,
                    'max' => null,
                ),
                'cost' => array(
                    'min' => $this->safe_number($options, 'defaultMinCost', 1),
                    'max' => null,
                ),
            ),
            'created' => null,
            'info' => $market,
        ));
    }

    public function fetch_tickers(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_tickers(...))($symbols, $params);
    }

    private function do_fetch_tickers(?array $symbols = null, $params = array()) {
        /**
         * fetches price tickers for multiple markets, the first snapshot request only subscribes to the market data, so the request is retried until data arrives
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-snapshot
         *
         * @param {string[]} $symbols unified $symbols of the markets to fetch the ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->fields] comma-separated snapshot field ids, max 50
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=ticker-structure ticker structures~
         */
        if ($symbols === null) {
            throw new ArgumentsRequired($this->id . ' fetchTickers() requires a symbols argument');
        }
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $symbolsNormalized = $this->market_symbols($symbols);
        list($fields, $query) = $this->handle_option_and_params($params, 'fetchTickers', 'fields');
        $fieldsString = implode(',', $fields);
        $response = Async\await($this->ibkr_fetch_snapshot($symbolsNormalized, $fieldsString, $query));
        //
        //     [
        //         {
        //             "31": "82838.50",
        //             "70": "85639.25",
        //             "71": "82209.75",
        //             "84": "82836.00",
        //             "85": "0.00018171",
        //             "86": "82843.75",
        //             "88": "0.27167244",
        //             "6509": "R",
        //             "7762": "78",
        //             "conidEx": "479624278",
        //             "_updated": 1791449398940,
        //             "conid": 479624278
        //         }
        //     ]
        //
        return $this->parse_tickers($response, $symbolsNormalized);
    }

    public function ibkr_fetch_snapshot(array $symbols, string $fields, $params = array(), ?array $readyFields = null): PromiseInterface {
        return Async\async(self::do_ibkr_fetch_snapshot(...))($symbols, $fields, $params, $readyFields);
    }

    private function do_ibkr_fetch_snapshot(array $symbols, string $fields, $params = array(), ?array $readyFields = null) {
        /**
         * fetches a $market data snapshot, the first snapshot $request only subscribes to the $market data, so the $request is retried until data arrives
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-$market-data/get-md-snapshot
         *
         * @param {string[]} $symbols unified $market $symbols
         * @param {string} $fields comma-separated snapshot field ids
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string[]} [$readyFields] the snapshot is ready once every item has at least one of these $fields, default array( '31', '84', '86' )
         * @return {array[]} the raw snapshot items
         */
        $conids = array();
        for ($i = 0; $i < count($symbols); $i++) {
            $market = $this->market($symbols[$i]);
            $conids[] = $this->safe_string($market, 'id', '');
        }
        $options = $this->safe_dict($this->options, 'fetchTickers', array());
        $retries = $this->safe_integer($options, 'retries', 5);
        $retryDelay = $this->safe_integer($options, 'retryDelay', 500);
        $request = array(
            'conids' => implode(',', $conids),
            'fields' => $fields,
        );
        $response = array();
        for ($i = 0; $i <= $retries; $i++) {
            $response = Async\await($this->webapiGetV1ApiIserverMarketdataSnapshot($this->extend($request, $params)));
            if ($this->ibkr_snapshot_ready($response, $readyFields)) {
                break;
            }
            if ($i < $retries) {
                Async\await($this->sleep($retryDelay));
            }
        }
        return $response;
    }

    public function ibkr_snapshot_ready(array $response, ?array $readyFields = null): bool {
        $numItems = count($response);
        if ($numItems === 0) {
            return false;
        }
        $fieldIds = ($readyFields === null) ? array( '31', '84', '86' ) : $readyFields;
        for ($i = 0; $i < count($response); $i++) {
            $item = $response[$i];
            $found = false;
            for ($j = 0; $j < count($fieldIds); $j++) {
                if ($this->safe_string($item, $fieldIds[$j]) !== null) {
                    $found = true;
                    break;
                }
            }
            if (!$found) {
                return false;
            }
        }
        return true;
    }

