    private function do_fetch_bids_asks(?array $symbols = null, $params = array()) {
        /**
         * fetches the bid and ask price and volume for multiple markets
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-snapshot
         *
         * @param {string[]} $symbols unified $symbols of the markets to fetch the bids and asks for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->fields] comma-separated snapshot field ids, default '84,85,86,88'
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=ticker-structure ticker structures~
         */
        if ($symbols === null) {
            throw new ArgumentsRequired($this->id . ' fetchBidsAsks() requires a symbols argument');
        }
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $symbolsNormalized = $this->market_symbols($symbols);
        $fields = $this->safe_string($params, 'fields', '84,85,86,88');
        $query = $this->omit($params, 'fields');
        $response = Async\await($this->ibkr_fetch_snapshot($symbolsNormalized, $fields, $query, array( '84', '86' )));
        //
        //     [ { "84": "82836.00", "85": "0.00018171", "86": "82843.75", "88": "0.27167244", "conidEx": "479624278", "_updated": 1791449398940, "conid": 479624278 } ]
