    }

    private function do_fetch_open_interests(?array $symbols = null, $params = array()) {
        /**
         * retrieves the open interest of multiple futures or swap markets
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-$market-data/get-md-snapshot
         *
         * @param {string[]} $symbols unified $symbols of the markets to fetch the open interest for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=open-interest-structure open interest structures~
         */
        if ($symbols === null) {
            throw new ArgumentsRequired($this->id . ' fetchOpenInterests() requires a symbols argument');
        }
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $symbolsNormalized = $this->market_symbols($symbols);
        for ($i = 0; $i < count($symbolsNormalized); $i++) {
            $market = $this->market($symbolsNormalized[$i]);
            if (!$market['contract']) {
                throw new BadRequest($this->id . ' fetchOpenInterests() supports contract markets only, ' . $market['symbol'] . ' is not a contract market');
            }
        }
        // 7697 futures open interest, 7638 option open interest, 31 last price for the open interest value
        $response = Async\await($this->ibkr_fetch_snapshot($symbolsNormalized, '31,7697,7638', $params, array( '7697', '7638' )));
        //
        //     [ { "31": "82838.50", "7697": "12345", "conidEx": "770561201", "_updated": 1791449398940, "conid": 770561201 } ]
        //
        return $this->parse_open_interests($response, $symbolsNormalized);
    }

    public function parse_open_interest(?array $interest, ?array $market = null): array {
        $marketId = $this->safe_string($interest, 'conid');
        $resolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($interest, '_updated');
        $openInterest = $this->ibkr_parse_value($this->safe_string_2($interest, '7697', '7638'));
        $last = $this->ibkr_parse_value($this->safe_string($interest, '31'));
        $contractSize = $this->safe_string($resolved, 'contractSize');
        $openInterestValue = null;
        if (($openInterest !== null) && ($last !== null) && ($contractSize !== null)) {
            $openInterestValue = Precise::string_mul(Precise::string_mul($openInterest, $contractSize), $last);
        }
        return $this->safe_open_interest(array(
            'symbol' => $resolved['symbol'],
            'openInterestAmount' => $this->parse_number($openInterest),
            'openInterestValue' => $this->parse_number($openInterestValue),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'info' => $interest,
        ), $resolved);
    }

