    private function do_fetch_status($params = array()) {
        /**
         * the $status of the brokerage session, 'ok' when $authenticated and $connected
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-brokerage-$status
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=exchange-$status-structure $status structure~
         */
        Async\await($this->authenticate());
        $response = Async\await($this->webapiPostV1ApiIserverAuthStatus($params));
        //
        //     {
        //         "authenticated": true,
        //         "competing": false,
        //         "connected": true,
        //         "message": "",
        //         "MAC": "12:B:B3:23:BF:A0",
        //         "serverInfo": { "serverName": "JifN19053", "serverVersion": "Build 10.25.0p, Dec 5, 2023 5:48:12 PM" },
        //         "fail": ""
        //     }
        //
        $authenticated = $this->safe_bool($response, 'authenticated', false);
        $connected = $this->safe_bool($response, 'connected', false);
        $status = ($authenticated && $connected) ? 'ok' : 'error';
        return array(
            'status' => $status,
            'updated' => null,
            'eta' => null,
            'url' => null,
            'info' => $response,
        );
    }

    public function ibkr_parse_value(?string $value): ?string {
        // snapshot values are formatted strings: "C82838.50" (prior close), "H1.2" (halted), "+1.04", "1.5%", "1M", "1,234", "$11,000K" (bond sizes, the principal amount)
        if (($value === null) || ($value === '') || ($value === 'N/A')) {
            return null;
        }
        $valueParts = explode(',', $value);
        $result = implode('', $valueParts);
        if (str_starts_with($result, 'C') || str_starts_with($result, 'H') || str_starts_with($result, '+') || str_starts_with($result, '$')) {
            $result = mb_substr($result, 1);
        }
        if (str_ends_with($result, '%')) {
            $result = mb_substr($result, 0, strlen($result) - 1 - 0);
        }
        $multiplier = null;
        if (str_ends_with($result, 'K')) {
            $multiplier = '1000';
        } elseif (str_ends_with($result, 'M')) {
            $multiplier = '1000000';
        } elseif (str_ends_with($result, 'B')) {
            $multiplier = '1000000000';
        }
        if ($multiplier !== null) {
            $scaled = Precise::string_mul(mb_substr($result, 0, strlen($result) - 1 - 0), $multiplier);
            if ($scaled === null) {
                return null;
            }
            $result = $scaled;
        }
        if ($result === '') {
            return null;
        }
        return $result;
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        $marketId = $this->safe_string($ticker, 'conid');
        $resolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($ticker, '_updated');
        $last = $this->ibkr_parse_value($this->safe_string($ticker, '7296')); // 31 might contain symbol
        if ($last === null) {
            // if precise fields are not provided, use generic "last price" field
            $last = $this->ibkr_parse_value($this->safe_string($ticker, '31'));
        }
        return $this->safe_ticker(array(
            'symbol' => $resolved['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $this->ibkr_parse_value($this->safe_string($ticker, '70')),
            'low' => $this->ibkr_parse_value($this->safe_string($ticker, '71')),
            'bid' => $this->ibkr_parse_value($this->safe_string($ticker, '84')),
            'bidVolume' => $this->ibkr_parse_value($this->safe_string($ticker, '88')),
            'ask' => $this->ibkr_parse_value($this->safe_string($ticker, '86')),
            'askVolume' => $this->ibkr_parse_value($this->safe_string($ticker, '85')),
            'vwap' => null,
            'open' => $this->ibkr_parse_value($this->safe_string($ticker, '7295')),
            'close' => $last,
            'last' => $last,
            'previousClose' => $this->ibkr_parse_value($this->safe_string($ticker, '7741')),
            'change' => $this->ibkr_parse_value($this->safe_string($ticker, '82')),
            'percentage' => $this->ibkr_parse_value($this->safe_string($ticker, '83')),
            'average' => null,
            'baseVolume' => $this->ibkr_parse_value($this->safe_string($ticker, '7762')),
            'quoteVolume' => null,
            'markPrice' => $this->ibkr_parse_value($this->safe_string($ticker, '7635')),
            'indexPrice' => null,
            'info' => $ticker,
        ), $resolved);
    }

    public function fetch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($symbol, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick $data containing the open, high, low, and close price, and the volume of a $market
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-$market-data/get-md-history
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV $data for
         * @param {string} $timeframe the length of time each candle represents
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch, max 1000
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {boolean} [$params->outsideRth] include $data outside regular trading hours
         * @param {string} [$params->source] 'Last', 'Bid_Ask' or 'Midpoint'
         * @return {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $maxLimit = $this->safe_integer($this->safe_dict($this->options, 'fetchOHLCV', array()), 'limit', 1000);
        $requestLimit = ($limit === null) ? $maxLimit : min($limit, $maxLimit);
        $duration = $this->parse_timeframe($timeframe);
        $request = array(
            'conid' => $market['id'],
            'bar' => $this->safe_string($this->timeframes, $timeframe, $timeframe),
        );
        if ($since !== null) {
            // startTime is exclusive, the first returned bar opens strictly after it, so the request starts one bar earlier
            // and the extra leading bar is removed by filterBySinceLimit in parseOHLCVs
            $request['startTime'] = $this->ibkr_format_time($since - $duration * 1000);
            $request['direction'] = '1'; // forward from startTime, by default startTime is the end of the range
            $requestLimit = min($requestLimit + 1, $maxLimit);
        }
        $request['period'] = $this->ibkr_period($duration, $requestLimit);
        $response = Async\await($this->webapiGetV1ApiIserverMarketdataHistory($this->extend($request, $params)));
        //
        //     {
        //         "points": 99,
        //         "startTime": "20261007-18:20:00",
        //         "data": [
        //             { "o": 336.94, "c": 336.89, "h": 336.97, "l": 336.85, "v": 1164.625, "t": 1791397200000 }
        //         ],
        //         ...
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_ohlcvs($data, $market, $timeframe, $since, $limit);
    }

    public function ibkr_period(int $duration, int $limit): string {
        // duration of one bar in seconds, the period is expressed in the largest fitting unit
        $total = $duration * $limit;
        if ($duration < 3600) {
            return $this->number_to_string($this->parse_to_int($total / 60)) . 'min';
        } elseif ($duration < 86400) {
            return $this->number_to_string($this->parse_to_int($total / 3600)) . 'h';
        } elseif ($duration < 604800) {
            return $this->number_to_string($this->parse_to_int($total / 86400)) . 'd';
        } elseif ($duration < 2592000) {
            return $this->number_to_string($this->parse_to_int($total / 604800)) . 'w';
        }
        // monthly bars, long month periods (e.g. "1000m") are rejected with "Chart data unavailable", so they are expressed in years
        $months = $this->parse_to_int($total / 2592000);
        if ($months <= 12) {
            return $this->number_to_string($months) . 'm';
        }
        $years = min($this->parse_to_int(($months + 11) / 12), 15); // 15y is the documented maximum period
        return $this->number_to_string($years) . 'y';
    }

    public function ibkr_format_time(int $timestamp): string {
        // YYYYMMDD-hh:mm:ss in UTC
        $iso = $this->iso8601($timestamp);
        return $this->yyyymmdd($timestamp, '') . '-' . mb_substr($iso, 11, 19 - 11);
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        return array(
            $this->safe_integer($ohlcv, 't'),
            $this->safe_number($ohlcv, 'o'),
            $this->safe_number($ohlcv, 'h'),
            $this->safe_number($ohlcv, 'l'),
            $this->safe_number($ohlcv, 'c'),
            $this->safe_number($ohlcv, 'v'),
        );
    }

