    private function do_fetch_accounts($params = array()) {
        /**
         * fetch all the $accounts associated with a profile
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-all-$accounts
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->method] 'privateGetPortfolioAccounts' (default) or 'privateGetPortfolioSubaccounts'
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=account-structure account structures~
         */
        // as required by IBKR, iserver/accounts must be called at least once before any other trading endpoint
        $portfolioAccounts = Async\await($this->fetch_portfolio_accounts($params));
        $accountIds = is_array($this->index_by($portfolioAccounts, 'accountId')) ? array_keys($this->index_by($portfolioAccounts, 'accountId')) : array();
        $length = count($accountIds);
        if ($length === 0) {
            throw new ExchangeError('No tradingaccount IDs found for the user');
        }
        if ($this->safe_string($this->options, 'accountId') === null) {
            if ($length === 1) {
                $this->options['accountId'] = $accountIds[0];
            } else {
                throw new ExchangeError('Multiple account IDs found, please set .options["accountId"] to desired one from => ' . implode(', ', $accountIds));
            }
        }
        $accounts = array();
        for ($i = 0; $i < count($portfolioAccounts); $i++) {
            $accounts[] = $this->parse_account($portfolioAccounts[$i]);
        }
        return $accounts;
    }

