         * switch the active account (for users with multiple accounts)
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-accounts/set-active-account
         *
         * @ignore
         * @param {string} $accountId the account id to switch to
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the raw $response from the exchange
         */
        if ($accountId === null) {
            throw new ArgumentsRequired($this->id . ' switchToAccount() requires an accountId argument');
        }
        $request = array(
            'acctId' => $accountId,
        );
        Async\await($this->authenticate());
        $response = Async\await($this->webapiPostV1ApiIserverAccount($this->extend($request, $params)));
