    public function create_order_request(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): array {
        /**
         * builds a single order ticket for createOrder and editOrder
         * @ignore
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the order ticket
         */
        $market = $this->market($symbol);
        $isMarket = ($type === 'market');
        $triggerPrice = $this->safe_string_2($params, 'triggerPrice', 'stopPrice');
        $trailingAmount = $this->safe_string($params, 'trailingAmount');
        $trailingPercent = $this->safe_string($params, 'trailingPercent');
        $clientOrderId = $this->safe_string_2($params, 'clientOrderId', 'cOID');
        $assetClass = $this->safe_string($market['info'], 'assetClass');
        $request = array(
            'conid' => $this->parse_to_int($market['id']),
            'side' => strtoupper($side),
        );
        // a market order with params['cost'] is sent by cost (cashQty) without a quantity
        $cost = $this->safe_string_2($params, 'cost', 'cashQty');
        $isMarketByCost = $isMarket && ($cost !== null);
        if (!$isMarketByCost) {
            $request['quantity'] = $this->parse_number($this->amount_to_precision($symbol, $amount));
        }
        $orderType = null;
        if (($trailingAmount !== null) || ($trailingPercent !== null)) {
            $orderType = $isMarket ? 'TRAIL' : 'TRAILLMT';
            if ($trailingPercent !== null) {
                $request['trailingType'] = '%';
                $request['trailingAmt'] = $this->parse_number($trailingPercent);
            } else {
                $request['trailingType'] = 'amt';
                $request['trailingAmt'] = $this->parse_number($this->price_to_precision($symbol, $trailingAmount));
            }
            if ($triggerPrice !== null) {
                $request['auxPrice'] = $this->parse_number($this->price_to_precision($symbol, $triggerPrice));
            }
            if (!$isMarket) {
                $request['price'] = $this->parse_number($this->price_to_precision($symbol, $price));
            }
        } elseif ($triggerPrice !== null) {
            if ($isMarket) {
                $orderType = 'STP';
                $request['price'] = $this->parse_number($this->price_to_precision($symbol, $triggerPrice));
            } else {
                $orderType = 'STP LMT';
                $request['price'] = $this->parse_number($this->price_to_precision($symbol, $price));
                $request['auxPrice'] = $this->parse_number($this->price_to_precision($symbol, $triggerPrice));
            }
        } elseif ($isMarket) {
            $orderType = 'MKT';
            if ($isMarketByCost) {
                $request['cashQty'] = $this->parse_number($this->price_to_precision($symbol, $cost));
            } elseif ($side === 'buy') {
                throw new InvalidOrder($this->id . ' createOrder() requires params["cost"] for market buy orders');
            }
        } else {
            $orderType = 'LMT';
            $request['price'] = $this->parse_number($this->price_to_precision($symbol, $price));
        }
        $request['orderType'] = $orderType;
        $defaultTimeInForce = 'DAY';
        if ($assetClass === 'CRYPTO') {
            $defaultTimeInForce = $isMarket ? 'IOC' : 'GTC';
        }
        $timeInForce = $this->safe_string_upper_2($params, 'timeInForce', 'tif', $defaultTimeInForce);
        $request['tif'] = $timeInForce;
        if ($clientOrderId === null) {
            $clientOrderId = 'ccxt' . $this->uuid22();
        }
        $request['cOID'] = $clientOrderId;
        $query = $this->omit($params, array( 'triggerPrice', 'stopPrice', 'trailingAmount', 'trailingPercent', 'clientOrderId', 'cOID', 'timeInForce', 'tif', 'cost', 'cashQty' ));
        $orderTicket = $this->extend($request, $query); // typed local, so the go transpiler returns a dict
        return $orderTicket;
    }

    public function ibkr_handle_order_replies(mixed $response, string $methodName): PromiseInterface {
        return Async\async(self::do_ibkr_handle_order_replies(...))($response, $methodName);
    }

    private function do_ibkr_handle_order_replies(mixed $response, string $methodName) {
        /**
         * confirms order reply prompts until the order is accepted, or throws InvalidOrder when $options->createOrder.autoConfirmOrderReplies is false
         * @ignore
         * @param {array} $response the order submission $response
         * @param {string} $methodName the calling method name
         * @return {array} the accepted order entry
         */
        $options = $this->safe_dict($this->options, 'createOrder', array());
        $autoConfirm = $this->safe_bool($options, 'autoConfirmOrderReplies', true);
        $maxReplies = $this->safe_integer($options, 'maxReplies', 10);
        $current = $response;
        for ($i = 0; $i <= $maxReplies; $i++) {
            if ((gettype($current) !== 'array' || array_keys($current) !== array_keys(array_keys($current)))) {
                //
                // advanced order reject
                //
                //     { "orderId": 123456789, "reqId": "22170", "text": "...", "options": [ ... ], "messageId": "p12", "prompt": true }
                //
                $text = $this->safe_string($current, 'text');
                throw new InvalidOrder($this->id . ' ' . $methodName . '() rejected => ' . $text);
            }
            $first = $this->safe_dict($current, 0, array());
            $orderId = $this->safe_string_2($first, 'order_id', 'orderId');
            if ($orderId !== null) {
                return $first;
            }
            //
            // reply prompt
            //
            //     [ { "id": "99097238-...", "isSuppressed": false, "message": [ "You are submitting an order without market data..." ], "messageIds": [ "o354" ] } ]
            //
            $replyId = $this->safe_string($first, 'id');
            $messages = $this->safe_list($first, 'message', array());
            $message = implode(' ', $messages);
            if ($replyId === null) {
                throw new InvalidOrder($this->id . ' ' . $methodName . '() unexpected response => ' . $this->json($current));
            }
            if (!$autoConfirm) {
                throw new InvalidOrder($this->id . ' ' . $methodName . '() requires confirmation (reply id ' . $replyId . ') => ' . $message);
            }
            $replyRequest = array(
                'replyId' => $replyId,
                'confirmed' => true,
            );
            $current = Async\await($this->webapiPostV1ApiIserverReplyReplyId($replyRequest));
        }
        throw new InvalidOrder($this->id . ' ' . $methodName . '() exceeded options.createOrder.maxReplies order reply confirmations');
    }

    public function edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_edit_order(...))($id, $symbol, $type, $side, $amount, $price, $params);
    }

    private function do_edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()) {
        /**
         * edit a trade $order
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/modify-open-$order
         *
         * @param {string} $id $order $id
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} [$amount] how much of the currency you want to trade in units of the base currency
         * @param {float} [$price] the $price at which the $order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint, see createOrder
         * @return {array} an ~@link https://docs.ccxt.com/?$id=$order-structure $order structure~
         */
        if ($amount === null) {
            throw new ArgumentsRequired($this->id . ' editOrder() requires an amount argument');
        }
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        list($accountId, $query) = Async\await($this->load_account_id($params));
        $orderRequest = $this->create_order_request($symbol, $type, $side, $amount, $price, $query);
        $orderRequest['acctId'] = $accountId;
        $orderRequest['accountId'] = $accountId;
        $orderRequest['orderId'] = $id;
        $response = Async\await($this->webapiPostV1ApiIserverAccountAccountIdOrderOrderId($orderRequest));
        $result = Async\await($this->ibkr_handle_order_replies($response, 'editOrder'));
        $order = $this->parse_order($result, $market);
        $order['type'] = $type;
        $order['side'] = $side;
        $order['amount'] = $amount;
        $order['price'] = $price;
        return $order;
    }

