    private function do_cancel_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * cancels an open order
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/cancel-open-order
         *
         * @param {string} $id order $id
         * @param {string} [$symbol] unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account $id, defaults to options["accountId"]
         * @return {array} an ~@link https://docs.ccxt.com/?$id=order-structure order structure~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        list($accountId, $query) = Async\await($this->load_account_id($params));
        $request = array(
            'accountId' => $accountId,
            'orderId' => $id,
        );
        $response = Async\await($this->webapiDeleteV1ApiIserverAccountAccountIdOrderOrderId($this->extend($request, $query)));
        //
        //     { "msg": "Request was submitted", "order_id": 123456789, "conid": 265598, "account": "U1234567" }
        //
        return $this->parse_order($response, $market);
    }

    public function fetch_order(string $id, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order(...))($id, $symbol, $params);
    }

    private function do_fetch_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * fetches information on an order made by the user, only orders of the current brokerage session are available
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-order-status
         *
         * @param {string} $id the order $id
         * @param {string} [$symbol] unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/?$id=order-structure order structure~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $request = array(
            'orderId' => $id,
        );
        $response = null;
        try {
            $response = Async\await($this->webapiGetV1ApiIserverAccountOrderStatusOrderId($this->extend($request, $params)));
            //
            //     {
            //         "order_id": 1799796559,
            //         "conid": 265598,
            //         "side": "BUY",
            //         "order_status": "Filled",
            //         "order_type": "MARKET",
            //         "size": "0.0",
            //         "total_size": "5.0",
            //         "cum_fill": "5.0",
            //         "average_price": "192.26",
            //         "tif": "DAY",
            //         "order_time": "231211180049",
            //         ...
            //     }
            //
        } catch (Exception $ex) {
            if ($ex instanceof InvalidProxySettings) {
                throw $ex; // rethrow this error since it means the user has a problem with their proxy settings that needs to be fixed
            }
            if ($ex instanceof OperationFailed) {
                throw $ex; // network-level failures are not the exchange saying the order is invalid
            }
            $message = $this->exception_message($ex);
            // eg:  {"error":"Order 54348392 is not found","statusCode":503}
            if (mb_strpos($message, 'is not found') !== false) {
                $newMessage = 'Order with id ' . $id . ' is not found, however it might be just because the time threshold has been passed for that order retrieval. Original message => ' . $message;
                throw new OrderNotFound($newMessage);
            } else {
                throw new InvalidOrder($message);
            }
        }
        if ($response === null) {
            throw new NullResponse($this->id . ' fetchOrder() returned empty response');
        }
        return $this->parse_order($response, $market);
    }

    public function fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
