    private function do_fetch_canceled_and_closed_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches information on multiple filled and canceled $orders of the current brokerage session
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-open-$orders
         *
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] the earliest time in ms to fetch $orders for
         * @param {int} [$limit] the maximum number of $order structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->filters] an exchange-side $status filter, by default all $orders are fetched and filtered by their unified $status
         * @param {boolean} [$params->force] refresh the cached $order list first, default true
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/?id=$order-structure $order structures~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $orders = Async\await($this->fetch_live_orders_raw($params));
        $parsed = $this->parse_orders($orders, $market, null, null);
        $result = array();
        for ($i = 0; $i < count($parsed); $i++) {
            $order = $parsed[$i];
            $status = $order['status'];
            if (($status === 'closed') || ($status === 'canceled')) {
                $result[] = $order;
            }
        }
        return $this->filter_by_symbol_since_limit($result, $symbol, $since, $limit);
    }

