    }

    private function do_fetch_orders_by_status_filter(string $status, ?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the live $orders, then keeps only the $orders with the given unified $status, the exchange-side filters are not used by default => a comma-separated list of them returns no $orders and each filter has its own cached list
         * @ignore
         * @param {string} $status unified order $status to keep, 'open', 'closed' or 'canceled'
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] the earliest time in ms to fetch $orders for
         * @param {int} [$limit] the maximum number of order structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/?id=order-structure order structures~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $orders = Async\await($this->fetch_live_orders_raw($params));
        $parsed = $this->parse_orders($orders, $market, null, null);
        $filtered = $this->filter_by($parsed, 'status', $status);
        return $this->filter_by_symbol_since_limit($filtered, $symbol, $since, $limit);
    }

    public function fetch_live_orders_raw($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_live_orders_raw(...))($params);
    }

    private function do_fetch_live_orders_raw($params = array()) {
        /**
         * fetches the raw live orders of the current brokerage session, refreshes the cached order list first ($options->fetchOrders.force) and retries once when the request only starts the order subscription
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-open-orders
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} the raw orders
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $options = $this->safe_dict($this->options, 'fetchOrders', array());
        $retryDelay = $this->safe_integer($options, 'retryDelay', 500);
        $force = $this->safe_bool($params, 'force', $this->safe_bool($options, 'force', true));
        $query = $this->omit($params, 'force');
        if ($force) {
            // the order list is cached and misses the orders created after it was built,
            // force = true clears the cache and returns an empty list, the next request returns the fresh list
            $forceRequest = array(
                'force' => true,
            );
            Async\await($this->webapiGetV1ApiIserverAccountOrders($forceRequest));
            Async\await($this->sleep($retryDelay));
        }
        $response = Async\await($this->webapiGetV1ApiIserverAccountOrders($query));
        if (!$this->safe_bool($response, 'snapshot', true)) {
            // the first request of a session only starts the order subscription
            Async\await($this->sleep($retryDelay));
            $response = Async\await($this->webapiGetV1ApiIserverAccountOrders($query));
        }
        //
        //    {
        //        "orders": [
        //            {
        //                "acct": "U3448646",
        //                "exchange": "PAXOS",
        //                "conidex": "495759171@PAXOS",
        //                "conid": 495759171,
        //                "account": "U3448646",
        //                "orderId": 2086144502,
        //                "cashCcy": "USD",
        //                "sizeAndFills": "0/0.01",
        //                "orderDesc": "Buy 0.01 ETH Crypto Limit 2000.00, Minutes",
        //                "description1": "ETH",
        //                "ticker": "ETH",
        //                "secType": "CRYPTO",
        //                "remainingQuantity": 0.01,
        //                "filledQuantity": 0,
        //                "totalSize": 0.01,
        //                "companyName": "Ethereum cryptocurrency",
        //                "status": "Cancelled",
        //                "order_ccp_status": null,
        //                "origOrderType": "LIMIT",
        //                "supportsTaxOpt": "1",
        //                "lastExecutionTime": "261021082714",
        //                "orderType": "Limit",
        //                "bgColor": "#FFFFFF",
        //                "fgColor": "#AA0000",
        //                "order_ref": "4649850",
        //                "isEventTrading": "0",
        //                "price": "2000.00",
        //                "timeInForce": "PAX",
        //                "lastExecutionTime_r": 1792571234000,
        //                "side": "BUY"
        //            }
        //        ],
        //        "snapshot": true
        //    }
        //
        return $this->safe_list($response, 'orders', array());
    }

    public function parse_order_status(?string $status): ?string {
        $statuses = array(
            'Inactive' => 'rejected',
            'PendingSubmit' => 'open',
            'PreSubmitted' => 'open',
            'Presubmitted' => 'open', // websocket sor topic
            'Submitted' => 'open',
            'Filled' => 'closed',
            'PendingCancel' => 'open',
            'PreCancelled' => 'canceled',
            'Cancelled' => 'canceled',
            'WarnState' => 'open',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_order_type(?string $orderType): ?string {
        if ($orderType === null) {
            return null;
        }
        $types = array(
            'LMT' => 'limit',
            'LIMIT' => 'limit',
            'MKT' => 'market',
            'MARKET' => 'market',
            'STP' => 'market',
            'STOP' => 'market',
            'STP LMT' => 'limit',
            'STOP_LIMIT' => 'limit',
            'STOPLIMIT' => 'limit',
            'TRAIL' => 'market',
            'TRAILLMT' => 'limit',
            'TRAILING_STOP' => 'market',
            'TRAILING_STOP_LIMIT' => 'limit',
            'MIDPRICE' => 'limit',
        );
        return $this->safe_string($types, strtoupper($orderType), $orderType);
    }

    public function parse_order_time_in_force(?string $timeInForce): ?string {
        $timeInForces = array(
            'DAY' => 'Day',
            'GTC' => 'GTC',
            'IOC' => 'IOC',
            'OPG' => 'OPG',
            'PAX' => 'PAX',
            'CLOSE' => 'Day',
        );
        return $this->safe_string($timeInForces, $timeInForce, $timeInForce);
    }

    public function parse_order(array $order, ?array $market = null): array {
        //
        // createOrder / editOrder
        //
        //     { "order_id": "1370093239", "order_status": "PreSubmitted", "encrypt_message": "1" }
        //
        // cancelOrder
        //
        //     { "msg": "Request was submitted", "order_id": 123456789, "conid": 265598, "account": "U1234567" }
        //  or
        //     { msg: 'Request was submitted', order_id: 1427813085, conid: -1, account: null }
        //
        // fetchOrder
        //
        //     { "order_id": 1799796559, "conid": 265598, "side": "BUY", "order_status": "Filled", "order_type": "MARKET", "size": "0.0", "total_size": "5.0", "cum_fill": "5.0", "average_price": "192.26", "tif": "DAY", "order_time": "231211180049" }
        //
        // fetchOrders
        //
        //     { "orderId": 1234568790, "conid": 265598, "side": "BUY", "status": "Submitted", "orderType": "Limit", "price": "185.50", "avgPrice": "185.40", "filledQuantity": 0.0, "remainingQuantity": 5.0, "totalSize": 5.0, "timeInForce": "CLOSE", "lastExecutionTime_r": 1702317649000, "order_ref": "my-id" }
        //
        $marketId = $this->safe_string($order, 'conid');
        // empty ids
        if ($marketId !== null && $marketId === '-1') {
            $marketId = null;
        }
        $resolved = $this->safe_market($marketId, $market);
        $orderTime = $this->safe_string($order, 'order_time');
        $timestamp = $this->safe_integer($order, 'lastExecutionTime_r');
        if (($timestamp === null) && ($orderTime !== null)) {
            // YYMMDDhhmmss in UTC
            $datetime = '20' . mb_substr($orderTime, 0, 2 - 0) . '-' . mb_substr($orderTime, 2, 4 - 2) . '-' . mb_substr($orderTime, 4, 6 - 4) . 'T' . mb_substr($orderTime, 6, 8 - 6) . ':' . mb_substr($orderTime, 8, 10 - 8) . ':' . mb_substr($orderTime, 10, 12 - 10) . 'Z';
            $timestamp = $this->parse8601($datetime);
        }
        $rawType = $this->safe_string_2($order, 'origOrderType', 'order_type');
        $orderType = $this->safe_string($order, 'orderType', $rawType);
        $sideId = $this->safe_string_upper($order, 'side');
        $side = null;
        if (($sideId === 'B') || ($sideId === 'BUY')) {
            $side = 'buy';
        } elseif (($sideId === 'S') || ($sideId === 'SELL')) {
            $side = 'sell';
        }
        return $this->safe_order(array(
            'id' => $this->safe_string_2($order, 'order_id', 'orderId'),
            'clientOrderId' => $this->safe_string_2($order, 'order_ref', 'cOID'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'lastUpdateTimestamp' => null,
            'symbol' => $resolved['symbol'],
            'type' => $this->parse_order_type($orderType),
            'timeInForce' => $this->parse_order_time_in_force($this->safe_string_2($order, 'timeInForce', 'tif')),
            'postOnly' => null,
            'reduceOnly' => null,
            'side' => $side,
            'price' => $this->omit_zero($this->safe_string_2($order, 'price', 'limit_price')),
            'triggerPrice' => $this->safe_string($order, 'auxPrice'),
            'amount' => $this->safe_string_2($order, 'totalSize', 'total_size'),
            'cost' => null,
            'average' => $this->omit_zero($this->safe_string_2($order, 'avgPrice', 'average_price')),
            'filled' => $this->safe_string_2($order, 'filledQuantity', 'cum_fill'),
            'remaining' => $this->safe_string_2($order, 'remainingQuantity', 'size'),
            'status' => $this->parse_order_status($this->safe_string_2($order, 'status', 'order_status')),
            'fee' => null,
            'trades' => null,
            'info' => $order,
        ), $resolved);
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all trades made by the user, over the last $days (max 7) via iserver/account/trades, or for crypto markets (which iserver/account/trades does not return) via pa/transactions
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-trade-history
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio-analyst/get-transactions
         *
         * @param {string} [$symbol] unified $market $symbol, required for crypto markets
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trades structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->days] number of $days to fetch, max 7 for iserver/account/trades, default 90 for pa/transactions
         * @param {string} [$params->method] 'privateGetIserverAccountTrades' or 'privatePostPaTransactions', default is 'privatePostPaTransactions' for crypto markets and 'privateGetIserverAccountTrades' otherwise
         * @param {string} [$params->currency] pa/transactions only, the currency to display the amounts in, default 'USD'
         * @param {string} [$params->accountId] pa/transactions only, the account id, defaults to $options["accountId"]
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/?id=trade-structure trade structures~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $options = $this->safe_dict($this->options, 'fetchMyTrades', array());
        $defaultMethod = 'privateGetIserverAccountTrades';
        if ($market !== null) {
            $assetClass = $this->safe_string($market['info'], 'assetClass');
            if ($assetClass === 'CRYPTO') {
                $defaultMethod = 'privatePostPaTransactions';
            }
        }
        $method = $this->safe_string($params, 'method', $defaultMethod);
        $query = $this->omit($params, 'method');
        if ($method === 'privatePostPaTransactions') {
            return Async\await($this->fetch_my_trades_from_transactions($market, $since, $limit, $query));
        }
        $days = $this->safe_integer($options, 'days', 7);
        if ($since !== null) {
            $daysPassed = ($this->milliseconds() - $since) / 86400000;
            $days = min(7, max(1, $this->parse_to_int((int) ceil($daysPassed))));
        }
        $request = array(
            'days' => $days,
        );
        $response = Async\await($this->webapiGetV1ApiIserverAccountTrades($this->extend($request, $query)));
        //
        //     [
        //         {
        //             "execution_id": "0000e0d5.6576fd38.01.01",
        //             "symbol": "BTC",
        //             "side": "B",
        //             "order_description": "Bot 0.0001 @ 82000",
        //             "trade_time_r": 1702319818000,
        //             "size": 0.0001,
        //             "price": "82000",
        //             "order_ref": "my-id",
        //             "exchange": "PAXOS",
        //             "commission": "0.02",
        //             "net_amount": 8.2,
        //             "account": "U1234567",
        //             "sec_type": "CRYPTO",
        //             "conidex": "479624278",
        //             "conid": 479624278,
        //             "order_id": 1234567890
        //         }
        //     ]
        //
        return $this->parse_trades($response, $market, $since, $limit);
    }

    public function fetch_my_trades_from_transactions(array $market, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades_from_transactions(...))($market, $since, $limit, $params);
    }

    private function do_fetch_my_trades_from_transactions(array $market, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the trades of a single $market via pa/transactions, used for crypto markets as iserver/account/trades does not return them
         * @ignore
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio-analyst/get-$transactions
         *
         * @param {array} $market the $market to fetch the trades for
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trades structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/?id=trade-structure trade structures~
         */
        if ($market === null) {
            throw new ArgumentsRequired($this->id . ' fetchMyTrades() requires a symbol argument when fetching trades from pa/transactions');
        }
        $options = $this->safe_dict($this->options, 'fetchMyTrades', array());
        list($accountId, $accountQuery) = Async\await($this->load_account_id($params));
        list($currency, $query) = $this->handle_option_and_params($accountQuery, 'fetchMyTrades', 'currency', $this->safe_string($options, 'transactionsCurrency', 'USD'));
        $days = $this->safe_integer($options, 'transactionsDays', 90);
        if ($since !== null) {
            $daysPassed = ($this->milliseconds() - $since) / 86400000;
            $days = max(1, $this->parse_to_int((int) ceil($daysPassed)));
        }
        $request = array(
            'acctIds' => array( $accountId ),
            'conids' => array( $this->parse_to_int($market['id']) ), // only one conid at a time is supported
            'currency' => $currency,
            'days' => $days,
        );
        $response = Async\await($this->webapiPostV1ApiPaTransactions($this->extend($request, $query)));
        //
        //     {
        //         "rc": 0,
        //         "nd": 4,
        //         "rpnl": { "data": [ ... ], "amt": "12.2516" },
        //         "currency": "USD",
        //         "from": 1702270800000,
        //         "id": "getTransactions",
        //         "to": 1702530000000,
        //         "includesRealTime": true,
        //         "transactions": [
        //             {
        //                 "date": "Mon Dec 11 00:00:00 EST 2023",
        //                 "cur": "USD",
        //                 "fxRate": 1,
        //                 "pr": 2428.04,
        //                 "qty": -0.01,
        //                 "acctid": "U1234567",
        //                 "amt": 24.28,
        //                 "conid": 495759171,
        //                 "type": "Sell",
        //                 "desc": "Ethereum"
        //             }
        //         ]
        //     }
        //
        $transactions = $this->safe_list($response, 'transactions', array());
        return $this->parse_trades($transactions, $market, $since, $limit);
    }

    public function parse_transaction_date(?string $date): ?int {
        // "Mon Dec 11 00:00:00 EST 2023" -> 2023-12-11T00:00:00-05:00
        if ($date === null) {
            return null;
        }
        $parts = explode(' ', $date);
        $partsLength = count($parts);
        if ($partsLength < 6) {
            return null;
        }
        $months = array(
            'Jan' => '01',
            'Feb' => '02',
            'Mar' => '03',
            'Apr' => '04',
            'May' => '05',
            'Jun' => '06',
            'Jul' => '07',
            'Aug' => '08',
            'Sep' => '09',
            'Oct' => '10',
            'Nov' => '11',
            'Dec' => '12',
        );
        $offsets = array(
            'EST' => '-05:00',
            'EDT' => '-04:00',
            'UTC' => '+00:00',
            'GMT' => '+00:00',
        );
        $month = $this->safe_string($months, $parts[1]);
        if ($month === null) {
            return null;
        }
        $dayPart = $parts[2];
        $day = str_pad($dayPart, 2, '0', STR_PAD_LEFT);
        $offset = $this->safe_string($offsets, $parts[4], '+00:00');
        return $this->parse8601($parts[5] . '-' . $month . '-' . $day . 'T' . $parts[3] . $offset);
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        if (is_array($trade) && array_key_exists('qty' ?? '', $trade)) {
            //
            // pa/transactions
            //
            //    {
            //        "cur": "USD",
            //        "date": "Thu Oct 08 00:00:00 EDT 2026",
            //        "rawDate": "20261008",
            //        "fxRate": 1,
            //        "pr": 2417.9,
            //        "qty": 0.08484221,
            //        "acctid": "U3448646",
            //        "amt": -205.139979559,
            //        "conid": 495759171,
            //        "type": "Buy",
            //        "desc": "Ethereum cryptocurrency",
            //        "isRealTime": false
            //    }
            //
            $transactionMarketId = $this->safe_string($trade, 'conid');
            $transactionMarket = $this->safe_market($transactionMarketId, $market);
            $transactionTimestamp = $this->parse_transaction_date($this->safe_string($trade, 'date'));
            $qty = $this->safe_string($trade, 'qty');
            $typeId = $this->safe_string_lower($trade, 'type');
            $transactionSide = null;
            if ($typeId === 'buy') {
                $transactionSide = 'buy';
            } elseif ($typeId === 'sell') {
                $transactionSide = 'sell';
            } elseif ($qty !== null) {
                $transactionSide = Precise::string_lt($qty, '0') ? 'sell' : 'buy';
            }
            return $this->safe_trade(array(
                'id' => null,
                'info' => $trade,
                'timestamp' => $transactionTimestamp,
                'datetime' => $this->iso8601($transactionTimestamp),
                'symbol' => $transactionMarket['symbol'],
                'order' => null,
                'type' => null,
                'side' => $transactionSide,
                'takerOrMaker' => null,
                'price' => $this->safe_string($trade, 'pr'),
                'amount' => Precise::string_abs($qty),
                'cost' => Precise::string_abs($this->safe_string($trade, 'amt')),
                'fee' => null,
            ), $transactionMarket);
        }
        $marketId = $this->safe_string($trade, 'conid');
        $resolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($trade, 'trade_time_r');
        $sideId = $this->safe_string($trade, 'side');
        $side = null;
        if (($sideId === 'B') || ($sideId === 'BUY')) {
            $side = 'buy';
        } elseif (($sideId === 'S') || ($sideId === 'SELL')) {
            $side = 'sell';
        }
        $commission = $this->safe_string($trade, 'commission');
        $fee = null;
        if ($commission !== null) {
            $fee = array(
                'cost' => $commission,
                'currency' => $resolved['quote'],
            );
        }
        return $this->safe_trade(array(
            'id' => $this->safe_string($trade, 'execution_id'),
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $resolved['symbol'],
            'order' => $this->safe_string($trade, 'order_id'),
            'type' => null,
            'side' => $side,
            'takerOrMaker' => null,
            'price' => $this->safe_string($trade, 'price'),
            'amount' => $this->safe_string($trade, 'size'),
            'cost' => null,
            'fee' => $fee,
        ), $resolved);
    }

    public function fetch_positions(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_positions(...))($symbols, $params);
    }

    private function do_fetch_positions(?array $symbols = null, $params = array()) {
        /**
         * fetch all open positions
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-uncached-positions
         *
         * @param {string[]} [$symbols] list of unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to options["accountId"]
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=position-structure position structure~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        list($accountId, $query) = Async\await($this->load_account_id($params));
        $request = array(
            'accountId' => $accountId,
        );
        $response = Async\await($this->webapiGetV1ApiPortfolio2AccountIdPositions($this->extend($request, $query)));
        //
        //     [
        //         {
        //             "position": 12.0,
        //             "conid": "265598",
        //             "avgCost": 192.5,
        //             "avgPrice": 192.5,
        //             "currency": "USD",
        //             "description": "AAPL",
        //             "isLastToLoq": false,
        //             "marketPrice": 193.12,
        //             "marketValue": 2317.44,
        //             "realizedPnl": 0.0,
        //             "secType": "STK",
        //             "timestamp": 1717444668,
        //             "unrealizedPnl": 7.44,
        //             "assetClass": "STK",
        //             "sector": "Technology",
        //             "group": "Computers",
        //             "model": ""
        //         }
        //     ]
        //
        return $this->parse_positions($response, $symbols);
    }

    public function fetch_positions_for_symbol(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_positions_for_symbol(...))($symbol, $params);
    }

    private function do_fetch_positions_for_symbol(string $symbol, $params = array()) {
        /**
         * fetch the open $positions of a single $market
         *
         * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-$position-by-conid
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->accountId] the account id, defaults to options["accountId"]
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=$position-structure $position structures~
         */
        Async\await($this->authenticate());
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        list($accountId, $query) = Async\await($this->load_account_id($params));
        $request = array(
            'accountId' => $accountId,
            'conid' => $market['id'],
        );
        $response = Async\await($this->webapiGetV1ApiPortfolioAccountIdPositionConid($this->extend($request, $query)));
        //
        //     [
        //         {
        //             "acctId": "U1234567",
        //             "conid": 265598,
        //             "contractDesc": "AAPL",
        //             "position": 614.2639,
        //             "mktPrice": 197.7639923,
        //             "mktValue": 121479.28,
        //             "currency": "USD",
        //             "avgCost": 192.7477563,
        //             "avgPrice": 192.7477563,
        //             "realizedPnl": 0.0,
        //             "unrealizedPnl": 3081.29,
        //             "assetClass": "STK",
        //             "model": ""
        //         }
        //     ]
        //
        $positions = (gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response))) ? $response : array();
        $result = array();
        for ($i = 0; $i < count($positions); $i++) {
            $position = $this->parse_position($positions[$i], $market);
            if (Precise::string_gt($this->safe_string($position, 'contracts', '0'), '0')) {
                $result[] = $position;
            }
        }
        return $result;
    }

    public function parse_position(array $position, ?array $market = null): array {
        $marketId = $this->safe_string($position, 'conid');
        $resolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_timestamp($position, 'timestamp');
        $contracts = $this->safe_string($position, 'position');
        $side = null;
        if (Precise::string_gt($contracts, '0')) {
            $side = 'long';
        } elseif (Precise::string_lt($contracts, '0')) {
            $side = 'short';
        }
        return $this->safe_position(array(
            'info' => $position,
            'id' => null,
            'symbol' => $resolved['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'isolated' => null,
            'hedged' => null,
            'side' => $side,
            'contracts' => $this->parse_number(Precise::string_abs($contracts)),
            'contractSize' => $this->safe_number($resolved, 'contractSize'),
            'entryPrice' => $this->safe_number_2($position, 'avgPrice', 'avgCost'),
            'markPrice' => $this->safe_number_2($position, 'marketPrice', 'mktPrice'),
            'notional' => $this->safe_number_2($position, 'marketValue', 'mktValue'),
            'leverage' => null,
            'collateral' => null,
            'initialMargin' => null,
            'maintenanceMargin' => null,
            'initialMarginPercentage' => null,
            'maintenanceMarginPercentage' => null,
            'unrealizedPnl' => $this->safe_number($position, 'unrealizedPnl'),
            'realizedPnl' => $this->safe_number($position, 'realizedPnl'),
            'liquidationPrice' => null,
            'marginMode' => null,
            'marginRatio' => null,
            'percentage' => null,
            'stopLossPrice' => null,
            'takeProfitPrice' => null,
            'lastUpdateTimestamp' => null,
        ));
    }

    public function ibkr_encrypt(string $value): string {
        // RFC 3986 percent-encoding (also escapes !'()*), as required by the oauth 1.0a signature base string
        $encoded = $this->urlencode(array( 'v' => $value ));
        return mb_substr($encoded, 2); // strip the 'v=' prefix
    }

    public function ibkr_base_string(string $method, string $url, array $params, string $prepend = ''): string {
        $query = $this->rawencode($this->keysort($params));
        return $prepend . $method . '&' . $this->ibkr_encrypt($url) . '&' . $this->ibkr_encrypt($query);
    }

    public function ibkr_auth_header(array $params): string {
        $sorted = $this->keysort($params);
        $keys = is_array($sorted) ? array_keys($sorted) : array();
        $parts = array();
        for ($i = 0; $i < count($keys); $i++) {
            $key = $keys[$i];
            $parts[] = $key . '="' . $sorted[$key] . '"';
        }
        return 'OAuth realm="' . $this->options['realm'] . '", ' . implode(', ', $parts);
    }

    public function ibkr_oauth_base(string $consumerKey, string $consumerAccessToken): array {
        return array(
            'oauth_consumer_key' => $consumerKey,
            'oauth_nonce' => $this->random_bytes(16),
            'oauth_timestamp' => (string) $this->seconds(),
            'oauth_token' => $consumerAccessToken,
        );
    }

    public function ibkr_implode_path(string $path, array $params): array {
        /**
         * replaces the ':name' $path parameters of the webapi endpoints with the matching values of $params
         * @ignore
         * @param {string} $path the endpoint $path, e.g. 'v1/api/iserver/account/:accountId/orders'
         * @param {array} $params the request $params, the $path $params are read from here
         * @return {Array} the imploded $path, e.g. 'v1/api/iserver/account/U1234567/orders', and the names of the $path $params
         */
        $segments = explode('/', $path);
        $pathParams = array();
        for ($i = 0; $i < count($segments); $i++) {
            $segment = $segments[$i];
            if (str_starts_with($segment, ':')) {
                $name = mb_substr($segment, 1);
                $pathParams[] = $name;
                $segments[$i] = $this->safe_string($params, $name, $segment);
            }
        }
        return array( implode('/', $segments), $pathParams );
    }

    public function ibkr_gateway_base_url(string $baseUrl, string $gatewayUrl): string {
        /**
         * maps an api.ibkr.com base url to the client portal $gateway url, e.g. 'https://api.ibkr.com/v1/api/' -> 'https://localhost:5000/v1/api/'
         * @ignore
         * @param {string} $baseUrl the configured api url
         * @param {string} $gatewayUrl options.gatewayUrl
         * @return {string} the $gateway base url
         */
        $gateway = $gatewayUrl;
        if (!str_ends_with($gateway, '/')) {
            $gateway = $gateway . '/';
        }
        $prefix = 'https://api.ibkr.com/';
        if (str_starts_with($baseUrl, $prefix)) {
            $path = str_replace($prefix, '', $baseUrl);
            return $gateway . $path;
        }
        return $baseUrl;
    }

    public function ibkr_check_oauth_credentials(): bool {
        /**
         * throws an AuthenticationError when the oauth 1.0a credentials (apiKey, secret and options.consumer_key) are missing, requiredCredentials can not be used for this, because the client portal gateway mode needs no credentials
         * @ignore
         * @return {boolean} true if the oauth credentials are set
         */
        if (($this->apiKey === null) || ($this->apiKey === '')) {
            throw new AuthenticationError($this->id . ' requires "apiKey" credential (the oauth access token), or set options["useGateway"] to use the client portal gateway');
        }
        if (($this->secret === null) || ($this->secret === '')) {
            throw new AuthenticationError($this->id . ' requires "secret" credential (the encrypted oauth access token secret), or set options["useGateway"] to use the client portal gateway');
        }
        $consumerKey = $this->safe_string($this->options, 'consumer_key');
        if (($consumerKey === null) || ($consumerKey === '')) {
            throw new AuthenticationError($this->id . ' requires options["consumer_key"] (the oauth consumer key), or set options["useGateway"] to use the client portal gateway');
        }
        return true;
    }

    public function ibkr_is_gateway_request(string $path): bool {
        /**
         * tells whether a request is routed to the client portal gateway instead of the oauth api
         * @ignore
         * @param {string} $path the endpoint $path
         * @return {boolean} true if the request is sent to the client portal gateway
         */
        // with the client portal gateway signIn () never sets a live session token, so besides options.useGateway
        // the requests are routed to the gateway when there is no live session token and oauth is not configured
        // (e.g. public calls like fetchOpenInterests made before any private call)
        $useGatewayOption = $this->safe_bool($this->options, 'useGateway', false);
        $hasLiveSessionToken = $this->safe_string($this->options, 'liveSessionToken') !== null;
        $oauthConfigured = ($this->safe_string($this->options, 'encryptionPemPath') !== null) && ($this->safe_string($this->options, 'dhParamPemPath') !== null);
        $isLiveSessionTokenRequest = str_ends_with($path, 'v1/api/oauth/live_session_token');
        return $useGatewayOption || (!$hasLiveSessionToken && !$oauthConfigured && !$isLiveSessionTokenRequest);
    }

    public function sign(string $path, array $api = array('public'), string $method = 'GET', $params = array()): array {
        list($implodedPath, $pathParams) = $this->ibkr_implode_path($path, $params);
        $apiBase = $api[0];
        $baseUrl = $this->urls['api'][$apiBase] . $implodedPath;
        $url = $baseUrl;
        $query = $this->omit($params, $pathParams);
        $hasQuery = count($query) > 0;
        $isGetOrDelete = ($method === 'GET') || ($method === 'DELETE');
        $requestBody = null;
        $requestHeaders = null;
        $isLiveSessionTokenRequest = str_ends_with($path, 'v1/api/oauth/live_session_token');
        if ($this->ibkr_is_gateway_request($path)) {
            // the client portal gateway holds the authenticated session, requests are sent unsigned
            $gatewayUrl = $this->safe_string($this->options, 'gatewayUrl');
            $url = $this->ibkr_gateway_base_url($this->urls['api'][$apiBase], $gatewayUrl) . $implodedPath;
            if ($isGetOrDelete) {
                if ($hasQuery) {
                    $url .= '?' . $this->urlencode($query);
                }
            } else {
                // the gateway rejects bodiless POST/PUT requests with http 411 (Length Required)
                $requestBody = $hasQuery ? $this->json($query) : '{}';
            }
            $requestHeaders = array(
                'Content-Type' => 'application/json',
                'User-Agent' => 'ccxt',
            );
            return array( 'url' => $url, 'method' => $method, 'body' => $requestBody, 'headers' => $requestHeaders );
        }
        $this->ibkr_check_oauth_credentials();
        $oauthParams = $this->ibkr_oauth_base($this->options['consumer_key'], $this->apiKey);
        if ($isLiveSessionTokenRequest) {
            // the live session token request is signed with RSA-SHA256,
            // its parameters (diffie_hellman_challenge) are sent as oauth parameters in the Authorization header
            $accessTokenSecretHex = $this->safe_string($this->options, 'accessTokenSecretHex', '');
            $signatureKey = $this->read_file($this->options['signaturePemPath']);
            $oauthParams['oauth_signature_method'] = 'RSA-SHA256';
            $authParams = $this->extend($oauthParams, $query);
            $auth = $this->ibkr_base_string($method, $baseUrl, $authParams, $accessTokenSecretHex);
            $signature = $this->rsa($auth, $signatureKey, 'sha256');
            $authParams['oauth_signature'] = $this->ibkr_encrypt($signature);
            $requestHeaders = array(
                'Authorization' => $this->ibkr_auth_header($authParams),
                'User-Agent' => 'ccxt',
            );
        } else {
            // private requests are signed with HMAC-SHA256 using the live session token obtained by signIn ()
            $liveSessionToken = $this->safe_string($this->options, 'liveSessionToken');
            if ($liveSessionToken === null) {
                throw new AuthenticationError($this->id . ' requires a live session token, call signIn() first (or set options.useGateway = true to use the client portal gateway)');
            }
            $oauthParams['oauth_signature_method'] = 'HMAC-SHA256';
            $signingParams = $oauthParams;
            if ($isGetOrDelete) {
                if ($hasQuery) {
                    $url .= '?' . $this->urlencode($query);
                    // the query-string params are part of the signature base string too
                    $signingParams = $this->extend($oauthParams, $query);
                }
            } elseif ($hasQuery) {
                $requestBody = $this->json($query);
            }
            $auth = $this->ibkr_base_string($method, $baseUrl, $signingParams);
            $signature = $this->hmac($this->encode($auth), base64_decode($liveSessionToken), 'sha256', 'base64');
            $oauthParams['oauth_signature'] = $this->ibkr_encrypt($signature);
            $requestHeaders = array(
                'Authorization' => $this->ibkr_auth_header($oauthParams),
                'Content-Type' => 'application/json',
                'User-Agent' => 'ccxt',
            );
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $requestBody, 'headers' => $requestHeaders );
    }

    public function ibkr_is_auth_request(string $path): bool {
        /**
         * tells whether the endpoint is used by signIn () itself, so it must not trigger authenticate ()
         * @ignore
         * @param {string} $path the endpoint $path
         * @return {boolean} true for the session/authentication endpoints
         */
        $authPaths = array(
            'v1/api/oauth/live_session_token',
            'v1/api/oauth/request_token',
            'v1/api/oauth/access_token',
            'v1/api/iserver/auth/status',
            'v1/api/iserver/auth/ssodh/init',
            'v1/api/iserver/accounts',
            'v1/api/tickle',
            'v1/api/logout',
        );
        return $this->in_array($path, $authPaths);
    }

    public function request(string $path, array $api = array('public'), mixed $method = 'GET', $params = array(), array $config = array()) {
        return Async\async(self::do_request(...))($path, $api, $method, $params, $config);
    }

    private function do_request(string $path, array $api = array('public'), mixed $method = 'GET', $params = array(), array $config = array()) {
        // every non-auth call renews an expired live session token (or re-checks the gateway session) first,
        // so methods that do not call authenticate () themselves never send a stale token
        if (!$this->ibkr_is_auth_request($path) && !$this->safe_bool($this->options, 'signInInProgress', false)) {
            Async\await($this->authenticate());
        }
        // right after a new brokerage session is opened, IBKR may still reject trading endpoints with
        // {"error":"Please query /accounts first"} even though iserver/accounts was already called,
        // so iserver/accounts is queried again and the request is retried
        if ($this->ibkr_is_gateway_request($path) && ($this->validateServerSsl !== false)) {
            // the gateway serves a self-signed certificate, so its validation is disabled, only in gateway mode (oauth requests to api.ibkr.com are always verified)
            // done here instead of sign (), which cannot change the instance in the statically typed ports
            $this->set_validate_server_ssl(false);
        }
        $isAccountsPath = ($path === 'iserver/accounts') || ($path === 'v1/api/iserver/accounts');
        $options = $this->safe_dict($this->options, 'queryAccountsFirst', array());
        $retries = $this->safe_integer($options, 'retries', 3);
        $retryDelay = $this->safe_integer($options, 'retryDelay', 1000);
        for ($i = 0; $i <= $retries; $i++) {
            try {
                return $this->do_fetch2($path, $api, $method, $params, $config);
            } catch (Exception $e) {
                $message = $this->exception_message($e, false);
                $mustQueryAccounts = mb_strpos($message, 'query /accounts first') !== false;
                if ($isAccountsPath || !$mustQueryAccounts || ($i === $retries)) {
                    throw $e;
                }
                $this->options['serviceAccountsLoaded'] = false;
                Async\await($this->webapiGetV1ApiIserverAccounts());
                $this->options['serviceAccountsLoaded'] = true;
                Async\await($this->sleep($retryDelay));
            }
        }
        return null;
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if (($code === 401) && $this->safe_bool($this->options, 'useGateway', false)) {
            // the gateway answers every request with 401 once its sso login is lost (daily reset, container restart, competing login)
            $this->options['gatewayAuthenticatedTimestamp'] = null;
            $gatewayUrl = $this->safe_string($this->options, 'gatewayUrl');
            throw new AuthenticationError($this->id . ' the client portal gateway is not logged in, log in again at ' . $gatewayUrl . ' in a browser. Current action => ' . $method . ' ' . $url . ' ' . $body);
        }
        if ($response === null) {
            return null; // fallback to default error handler
        }
        //
        //     {
        //         "error": "Bad Request: Conid(s) missing",
        //         "statusCode": 400
        //     }
        //
        $errorMessage = $this->safe_string($response, 'error');
        if ($errorMessage !== null) {
            $feedback = $this->id . ' ' . $body;
            $statusCode = $this->safe_string($response, 'statusCode');
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $statusCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $errorMessage, $feedback);
            throw new ExchangeError($feedback); // unknown message
        }
        return null;
    }
}
